#!/usr/bin/env node
// cavecrew model overrides — patch installed agent frontmatter from env vars.
//
// Called by caveman-activate.js early in SessionStart so users can pin
// per-agent models without shadow-copying entire agent files.
//
// Env vars:
//   CAVECREW_REVIEWER_MODEL    → agents/cavecrew-reviewer.md
//   CAVECREW_BUILDER_MODEL     → agents/cavecrew-builder.md
//   CAVECREW_INVESTIGATOR_MODEL → agents/cavecrew-investigator.md
//
// Rules:
//   - Unset / blank → no-op.
//   - Values containing newlines or control characters → ignored.
//   - Existing `model:` line in frontmatter → replaced in-place.
//   - No `model:` line → inserted after `tools:` (or before closing `---`).
//   - File missing / outside plugin layout → silent no-op.
//   - All filesystem errors → silent fail.

const fs = require('fs');
const path = require('path');

const AGENT_ENV_MAP = [
  { envVar: 'CAVECREW_REVIEWER_MODEL',     file: path.join('agents', 'cavecrew-reviewer.md') },
  { envVar: 'CAVECREW_BUILDER_MODEL',      file: path.join('agents', 'cavecrew-builder.md') },
  { envVar: 'CAVECREW_INVESTIGATOR_MODEL', file: path.join('agents', 'cavecrew-investigator.md') },
];

// Return the plugin root directory given the hooks directory path.
// Layouts (#645): plugin/repo checkout puts this file at <root>/src/hooks/
// (agents/ lives two levels up); standalone installs at <config>/hooks/
// (one level up). Prefer CLAUDE_PLUGIN_ROOT, then the first candidate that
// actually contains an agents/ directory.
function resolvePluginRoot(hookDir) {
  const candidates = [];
  if (process.env.CLAUDE_PLUGIN_ROOT) candidates.push(process.env.CLAUDE_PLUGIN_ROOT);
  candidates.push(path.resolve(hookDir, '..', '..'), path.resolve(hookDir, '..'));
  for (const root of candidates) {
    try {
      if (fs.statSync(path.join(root, 'agents')).isDirectory()) return root;
    } catch (e) {}
  }
  return path.resolve(hookDir, '..');
}

// Patch the YAML frontmatter of `content` to set `model: <modelValue>`.
// Returns the patched string, or the original if no frontmatter or already identical.
// Rejects `modelValue` strings that contain newlines or control characters.
function patchFrontmatterModel(content, modelValue) {
  // Reject blank or unsafe model strings
  if (!modelValue || /[\x00-\x1f\x7f]/.test(modelValue)) return content;

  // Must begin with YAML frontmatter delimiter
  if (!content.startsWith('---')) return content;

  // Find the closing ---
  const closeIdx = content.indexOf('\n---', 3);
  if (closeIdx === -1) return content;

  const fmRaw = content.slice(0, closeIdx);           // opening --- through last fm line
  const after  = content.slice(closeIdx);             // \n--- onward (body)

  // Preserve original line ending so we don't create mixed CRLF/LF on Windows
  const nl = fmRaw.includes('\r\n') ? '\r\n' : '\n';

  const modelLine = 'model: ' + modelValue;
  const modelRe   = /^model:[ \t]*.*$/m;

  if (modelRe.test(fmRaw)) {
    // Replace existing model: line
    const patched = fmRaw.replace(modelRe, modelLine);
    if (patched === fmRaw) return content;            // already identical
    return patched + after;
  }

  // Insert after tools: line when present; else before closing ---
  const toolsMatch = fmRaw.match(/^tools:[ \t]*.*$/m);
  if (toolsMatch) {
    const toolsEnd = fmRaw.indexOf(toolsMatch[0]) + toolsMatch[0].length;
    return fmRaw.slice(0, toolsEnd) + nl + modelLine + fmRaw.slice(toolsEnd) + after;
  }

  // Append before closing delimiter
  return fmRaw + nl + modelLine + after;
}

// insideGitWorkTree reports whether `dir` sits inside a git working tree.
//
// A plugin root inside one is a SOURCE CHECKOUT, not an installed plugin:
// resolvePluginRoot returns the repo root when this hook runs from a clone, so
// with any CAVECREW_*_MODEL set, EVERY SessionStart rewrote tracked agents/*.md
// and dirtied the working tree just by opening the repo. An installed plugin
// lives under $CLAUDE_CONFIG_DIR with no .git above it, so overrides still apply
// there — the one place they can be applied without editing someone's source.
function insideGitWorkTree(dir) {
  let current = path.resolve(dir);
  for (let i = 0; i < 64; i++) {
    try {
      if (fs.existsSync(path.join(current, '.git'))) return true;
    } catch (e) { /* unreadable ancestor → keep walking */ }
    const parent = path.dirname(current);
    if (parent === current) return false;
    current = parent;
  }
  return false;
}

// Apply all env-var overrides to agent files under `pluginRoot`.
// `env` defaults to process.env; pass an object in tests.
function applyOverrides(pluginRoot, env) {
  const envArg = env || process.env;
  if (insideGitWorkTree(pluginRoot)) return;
  for (const { envVar, file } of AGENT_ENV_MAP) {
    const raw = envArg[envVar];
    if (!raw || !raw.trim()) continue;

    const modelValue = raw.trim();
    if (/[\x00-\x1f\x7f]/.test(modelValue)) continue;

    const agentPath = path.join(pluginRoot, file);
    let content;
    try {
      content = fs.readFileSync(agentPath, 'utf8');
    } catch (e) {
      continue; // missing file or wrong layout → silent no-op
    }

    const patched = patchFrontmatterModel(content, modelValue);
    if (patched === content) continue;

    try {
      fs.writeFileSync(agentPath, patched, 'utf8');
    } catch (e) {
      // Silent fail — never block session start
    }
  }
}

module.exports = { resolvePluginRoot, patchFrontmatterModel, applyOverrides, insideGitWorkTree, AGENT_ENV_MAP };

#!/usr/bin/env node
// caveman — Claude Code SessionStart activation hook
//
// Runs on every session start:
//   1. Resolves THIS session's mode and persists it (statusline reads it)
//   2. Emits caveman ruleset as hidden SessionStart context
//   3. Detects missing statusline config and emits setup nudge
//
// Mode state is per session, not per machine — see the "Per-session mode state"
// block in caveman-config.js. The payload's session_id scopes every read and
// write below; an absent or malformed one degrades to the old machine-wide flag.

const fs = require('fs');
const path = require('path');
const os = require('os');
// caveman-config.js is a mandatory sibling, but an incomplete install (plugin
// cache drift, a copy list that missed a file) leaves it absent. A bare
// top-level require turns that into an uncaught MODULE_NOT_FOUND on EVERY
// session start, which Claude Code surfaces only as an opaque loader stack
// trace (#848). Resolve it defensively and degrade instead.
//
// Deliberately inlined here rather than extracted into a shared helper: a
// shared loader would itself be one more sibling that can go missing, which
// is the exact failure this guards against.
function reportDegraded(name, detail) {
  process.stderr.write('caveman: ' + detail + '\n'
    + 'Run `/plugin update caveman`, or rerun install.sh for standalone hooks. '
    + 'Continuing with reduced functionality.\n');
}

function requireSibling(name, isUsable) {
  let mod;
  try {
    mod = require('./' + name);
  } catch (primary) {
    // The opencode install layout renames the sibling to `.cjs` (its plugin
    // dir is "type": "module"), same fallback caveman-parse.js already does.
    // Gate the retry on the error naming THIS module: a MODULE_NOT_FOUND
    // thrown by a require *inside* a sibling that loaded fine must not be
    // re-reported as "./<name>.cjs is missing", which blames a file that was
    // never meant to exist.
    const message = String((primary && primary.message) || primary);
    if (primary && primary.code === 'MODULE_NOT_FOUND' && message.includes("'./" + name + "'")) {
      try { return require('./' + name + '.cjs'); } catch (e) { /* report primary */ }
    }
    const absent = !fs.existsSync(path.join(__dirname, name + '.js'))
                && !fs.existsSync(path.join(__dirname, name + '.cjs'));
    // Distinguish "the sibling is absent" from "the sibling loaded but its
    // own require failed" — naming the wrong cause is worse than no message.
    // Only the first line of error.message: Node appends a multi-line
    // "Require stack:" block, which is the noise this guard exists to remove.
    reportDegraded(name, absent
      ? name + '.js is missing from ' + __dirname + ' — the install is incomplete.'
      : name + ' could not load — ' + message.split('\n')[0]);
    return null;
  }
  // A module that LOADS but exports the wrong shape is the plugin-cache-drift
  // case #848 actually describes: a stale sibling from another version. Without
  // this check the destructure below succeeds and the first use dereferences
  // undefined, producing exactly the raw top-level stack trace and exit 1 this
  // guard exists to remove. Validate the shape, not just the throw.
  if (!isUsable(mod)) {
    reportDegraded(name, name + ' loaded but is missing expected exports — the install is inconsistent.');
    return null;
  }
  return mod;
}

// Hand-copy of caveman-config.js VALID_MODES, used only when that module is
// unavailable. tests/test_hook_missing_sibling.js asserts the two stay equal.
const FALLBACK_VALID_MODES = [
  'off', 'lite', 'full', 'ultra',
  'wenyan-lite', 'wenyan', 'wenyan-full', 'wenyan-ultra',
  'commit', 'review', 'compress'
];

// Minimal stand-in for caveman-config.getDefaultMode. It must mirror the real
// resolution order rather than read only the env var: a degrade that ignores a
// checked-in `.caveman.json` or a user config saying `defaultMode: "off"` does
// not degrade toward the user's intent, it INVERTS it — a team that opted out
// would get caveman force-injected the moment one file goes missing. Reads
// only; refuses symlinked config files, symmetric with safeWriteFlag.
function fallbackReadMode(file) {
  try {
    if (!fs.lstatSync(file).isFile()) return null;
    const mode = JSON.parse(fs.readFileSync(file, 'utf8')).defaultMode;
    if (typeof mode === 'string' && FALLBACK_VALID_MODES.includes(mode.toLowerCase())) {
      return mode.toLowerCase();
    }
  } catch (e) { /* absent, unreadable, or malformed → next source */ }
  return null;
}

function fallbackUserConfigPath() {
  if (process.env.XDG_CONFIG_HOME) return path.join(process.env.XDG_CONFIG_HOME, 'caveman', 'config.json');
  if (process.platform === 'win32') {
    return path.join(process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'), 'caveman', 'config.json');
  }
  return path.join(os.homedir(), '.config', 'caveman', 'config.json');
}

function fallbackGetDefaultMode(startDir) {
  // 1. Environment variable. No .trim() — the real resolver does not trim, and
  //    a degraded path that accepts " ultra" where the intact one rejects it is
  //    drift in a whitelist.
  const envMode = process.env.CAVEMAN_DEFAULT_MODE;
  if (envMode && FALLBACK_VALID_MODES.includes(envMode.toLowerCase())) return envMode.toLowerCase();
  // 2. Repo-local config, walking up. Bounded at 64 like findRepoConfigPath.
  try {
    let dir = path.resolve(startDir || process.cwd());
    for (let i = 0; i < 64; i++) {
      for (const rel of ['.caveman/config.json', '.caveman.json']) {
        const mode = fallbackReadMode(path.join(dir, rel));
        if (mode) return mode;
      }
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  } catch (e) { /* fall through to user config */ }
  // 3. User config, then 4. the built-in default.
  return fallbackReadMode(fallbackUserConfigPath()) || 'full';
}

// Degraded stubs keep the rest of this hook working when the config module is
// unusable: the session still gets its ruleset (read from SKILL.md, which does
// not depend on the config module) and only flag persistence is lost — no flag
// write, no mode log, readFlag() reports nothing active.
const cavemanConfig = requireSibling('caveman-config', (m) =>
  m && typeof m.getDefaultMode === 'function' && typeof m.safeWriteFlag === 'function'
    && typeof m.recordModeChange === 'function' && typeof m.readFlag === 'function'
    && Array.isArray(m.VALID_MODES));

const { getDefaultMode, safeWriteFlag, recordModeChange, readFlag, VALID_MODES } = cavemanConfig || {
  getDefaultMode: fallbackGetDefaultMode,
  safeWriteFlag: () => {},
  recordModeChange: () => {},
  readFlag: () => null,
  VALID_MODES: FALLBACK_VALID_MODES,
};

const claudeDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
const flagPath = path.join(claudeDir, '.caveman-active');
const settingsPath = path.join(claudeDir, 'settings.json');

function removeFlag(target) {
  try {
    fs.unlinkSync(target);
  } catch (error) {
    if (process.env.CAVEMAN_DEBUG === '1' && error.code !== 'ENOENT') {
      console.error(`caveman: failed to remove flag ${target}: ${error.message}`);
    }
  }
}

// The per-session helpers are resolved INDIVIDUALLY rather than folded into the
// requireSibling shape check above. A caveman-config.js from before per-session
// state loads fine and exports everything that check demands, so failing the
// whole module over the newer exports would trade "machine-wide mode, as it
// always worked" for "no flag write at all" — a strictly worse degrade on the
// exact plugin-cache-drift scenario #848 is about. Each stub below reproduces
// the pre-per-session behavior instead.
const cfg = cavemanConfig || {};
const validateSessionId = cfg.validateSessionId || (() => null);
const gcSessionStore = cfg.gcSessionStore || (() => 0);
// Literal read of THIS session's state, 'off' included. Degrades to the legacy
// flag, which is exactly what the pre-per-session hook read.
const readSessionModeRaw = cfg.readSessionModeRaw || (() => readFlag(flagPath));
const writeSessionMode = cfg.writeSessionMode || ((dir, sid, modeOrNull) => {
  if (!modeOrNull || modeOrNull === 'off') removeFlag(flagPath);
  else safeWriteFlag(flagPath, modeOrNull);
});
const legacyFlagPath = cfg.legacyFlagPath || (() => flagPath);

// Apply per-agent model overrides from env vars before emitting rules.
// Best-effort: any error is swallowed so SessionStart is never blocked.
try {
  const { applyOverrides, resolvePluginRoot } = require('./cavecrew-model-overrides');
  applyOverrides(resolvePluginRoot(__dirname));
} catch (e) {}

// SessionStart re-fires mid-conversation (resume, /clear, context compaction),
// not just at true session start. Re-firing must not clobber a mode the user
// switched to mid-session (#691): branch on the hook payload's `source` field —
// only a real `startup` (or an explicit /clear, see RESET_SOURCES) resets to the
// configured default; resume/compact/fork preserve this session's stored mode.
//
// With per-session storage the branch also has to preserve a durable `off`.
// #691 could not: it read the legacy flag, where "off" is spelled "no file", so
// a deactivated session found nothing stored and fell straight back to
// getDefaultMode() — the "stop caveman, then /compact" hole. The continuation
// branch below therefore reads the LITERAL stored value, not the collapsed one.
// Payload arrival is EVENT-DRIVEN, and activation runs on the first COMPLETE
// JSON object rather than at EOF. The host writes one object and closes, but
// under the Windows pipe implementation that close can lag arbitrarily
// (#729/#833). A synchronous `readFileSync(0)` blocks inside the read syscall
// until EOF — no deadline can interrupt it — so a lagging close spent this
// hook's entire 5s budget and the host killed it before the flag was written or
// the ruleset emitted. caveman-mode-tracker.js was fixed this way; its sibling
// was not, and SessionStart is the one that actually has work to do.
//
// A watchdog covers the case where the payload never completes at all: activate
// well inside the budget instead of forfeiting the session. It must NOT assume
// `startup` — that is the one source that resets the mode, so a slow payload on
// a `compact`/`resume` event would silently drop a user's mid-session `ultra`
// back to the default (#691 through the timeout door). An unknown source
// preserves a valid existing flag. The deadline sits well below the host's 5s
// budget but far enough above a cold Windows/AV start to be reached rarely.
const PAYLOAD_WATCHDOG_MS = 2000;

// Sources that re-derive the configured default instead of reading what this
// session already stored.
//
// `startup` is a genuinely new session. `clear` is here — unlike in #691's
// flag-only world — because /clear is an explicit user reset of the
// conversation, and per-session storage makes that distinction cheap: nothing
// else in the session survives /clear, so neither should a "stop caveman" from
// before it. Everything else (compact, resume, fork, an unrecognized source,
// and the watchdog's 'unknown') reads instead of re-deriving.
const RESET_SOURCES = new Set(['startup', 'clear']);

function activate(payload, timedOut) {
  // Unknown, not startup: we never saw the payload, so we cannot claim to know
  // what kind of session event this was — and 'unknown' must not reset, or a
  // slow payload on a compact would drop a mid-session ultra (#691 through the
  // timeout door) and re-arm a session the user turned off.
  let source = timedOut ? 'unknown' : 'startup';
  // The session's cwd, which is not necessarily this hook process's cwd. The
  // repo-local config walk must start there or a checked-in .caveman.json
  // (including `defaultMode: "off"`, a project opting out) is missed — the same
  // #634 bug already fixed in caveman-mode-tracker.js.
  let sessionCwd;
  // Scopes every mode read/write to this window. null when absent or malformed,
  // in which case the config helpers fall back to the legacy machine-wide flag.
  let sessionId = null;
  try {
    if (payload) {
      const data = JSON.parse(payload);
      if (data && typeof data.source === 'string') source = data.source;
      if (data && typeof data.cwd === 'string') sessionCwd = data.cwd;
      if (data) sessionId = validateSessionId(data.session_id);
    }
  } catch (e) { /* no/bad stdin → treat as startup */ }
  run(source, sessionCwd, sessionId);
}

if (process.stdin.isTTY) {
  // Manual run — no payload is coming.
  activate('');
} else {
  let input = '';
  let done = false;
  const finish = (timedOut) => {
    if (done) return;
    done = true;
    clearTimeout(watchdog);
    // Attaching a 'data' listener puts the stdin handle into flowing mode and
    // REFERENCES it, so pause() alone leaves the event loop alive and the
    // process never exits while the host holds the write end open — which is
    // exactly the lagging-close case this rewrite exists to survive. unref()
    // drops the handle from the loop's ref count without closing the fd, so we
    // exit as soon as stdout has flushed.
    try { process.stdin.pause(); } catch (e) {}
    try { process.stdin.unref(); } catch (e) {}
    activate(input, timedOut === true);
  };
  const watchdog = setTimeout(() => finish(true), PAYLOAD_WATCHDOG_MS);
  // StringDecoder semantics: a multi-byte character split across two chunks is
  // held until complete, rather than each half becoming a replacement char.
  process.stdin.setEncoding('utf8');
  process.stdin.on('data', (chunk) => {
    input += chunk;
    // A partial payload throws here and we simply wait for more bytes.
    try { JSON.parse(input); } catch (e) { return; }
    finish();
  });
  // Abnormal close (broken pipe, parent crash) emits 'error'; without a
  // listener Node throws it as an uncaught exception and the hook exits
  // non-zero — a spurious hook failure (#538). Hooks must always exit 0.
  process.stdin.on('error', () => finish());
  process.stdin.on('end', () => finish());
}

function run(source, sessionCwd, sessionId) {
let mode;
if (RESET_SOURCES.has(source)) {
  mode = getDefaultMode(sessionCwd);
  // Sweep stale per-session files only when a session genuinely begins, not on
  // every compaction — those are frequent in a long session and this walks a
  // directory inside a 5s hook budget.
  gcSessionStore(claudeDir);
} else {
  // Continuation: read, never re-derive. The LITERAL value, so a stored 'off'
  // is distinguishable from "nothing stored yet".
  let stored = readSessionModeRaw(claudeDir, sessionId);
  // Upgrade path: a session that began before per-session state exists only in
  // the legacy mirror. Falling through to the default there would re-derive on
  // the very compaction #691 fixed. The mirror never holds the literal 'off',
  // so this can only ever supply a real mode.
  if (stored === null) stored = readFlag(legacyFlagPath(claudeDir));
  if (stored && VALID_MODES.includes(stored)) {
    mode = stored;
  } else {
    // resume/fork can carry a session id we have never seen (a fork gets a new
    // one). With nothing stored anywhere, fall back to the configured default.
    mode = getDefaultMode(sessionCwd);
  }
}

// "off" mode — skip activation entirely, don't emit rules. The state is still
// written so the choice survives this session's later compactions: that write
// is what closes the "stop caveman → /compact re-arms caveman" hole, because
// the next SessionStart finds a durable 'off' instead of an absent file.
if (mode === 'off') {
  recordModeChange(claudeDir, null, sessionId); // #601: timestamped transition log
  writeSessionMode(claudeDir, sessionId, null);
  process.stdout.write('OK');
  process.exit(0);
}

// 1. Persist this session's mode (symlink-safe, mirrored to the legacy flag)
recordModeChange(claudeDir, mode, sessionId); // #601
writeSessionMode(claudeDir, sessionId, mode);

// 2. Emit full caveman ruleset, filtered to the active intensity level.
//    The old 2-sentence summary was too weak — models drifted back to verbose
//    mid-conversation, especially after context compression pruned it away.
//    Full rules with examples anchor behavior much more reliably.
//
//    Reads SKILL.md at runtime so edits to the source of truth propagate
//    automatically — no hardcoded duplication to go stale.

// Modes that have their own independent skill files — not caveman intensity levels.
// For these, emit a short activation line; the skill itself handles behavior.
const INDEPENDENT_MODES = new Set(['commit', 'review', 'compress']);

if (INDEPENDENT_MODES.has(mode)) {
  process.stdout.write('CAVEMAN MODE ACTIVE — level: ' + mode + '. Behavior defined by /caveman-' + mode + ' skill.');
  process.exit(0);
}

// Resolve the canonical label for wenyan alias
const modeLabel = mode === 'wenyan' ? 'wenyan-full' : mode;

// Read SKILL.md — the single source of truth for caveman behavior.
// Candidate locations, tried in order (#587/#589 — the old single '..' path
// resolved to <plugin_root>/src/skills/, which doesn't exist, so plugin
// installs silently used the stale fallback ruleset):
//   1. $CLAUDE_PLUGIN_ROOT/skills/caveman/SKILL.md — Claude Code sets
//      CLAUDE_PLUGIN_ROOT when invoking plugin hooks; authoritative when present.
//   2. ../../skills/caveman/SKILL.md — hook at <plugin_root>/src/hooks/
//      (plugin.json layout) or a repo checkout.
//   3. ../skills/caveman/SKILL.md — standalone install with hooks at
//      $CLAUDE_CONFIG_DIR/hooks/ and the skill at $CLAUDE_CONFIG_DIR/skills/caveman/.
// All misses fall through to the hardcoded fallback ruleset below.
const skillCandidates = [];
if (process.env.CLAUDE_PLUGIN_ROOT) {
  skillCandidates.push(path.join(process.env.CLAUDE_PLUGIN_ROOT, 'skills', 'caveman', 'SKILL.md'));
}
skillCandidates.push(
  path.join(__dirname, '..', '..', 'skills', 'caveman', 'SKILL.md'),
  path.join(__dirname, '..', 'skills', 'caveman', 'SKILL.md')
);

let skillContent = '';
for (const candidate of skillCandidates) {
  try {
    skillContent = fs.readFileSync(candidate, 'utf8');
    break;
  } catch (e) { /* try next candidate */ }
}

let output;

if (skillContent) {
  // Strip YAML frontmatter
  const body = skillContent.replace(/^---[\s\S]*?---\s*/, '');

  // Filter intensity table: keep header rows + only the active level's row
  const filtered = body.split('\n').reduce((acc, line) => {
    // Intensity table rows start with | **level** |
    const tableRowMatch = line.match(/^\|\s*\*\*(\S+?)\*\*\s*\|/);
    if (tableRowMatch) {
      // Keep only the active level's row (and always keep header/separator)
      if (tableRowMatch[1] === modeLabel) {
        acc.push(line);
      }
      return acc;
    }

    // Example lines start with "- level:" — keep only lines matching active level
    const exampleMatch = line.match(/^- (\S+?):\s/);
    if (exampleMatch) {
      if (exampleMatch[1] === modeLabel) {
        acc.push(line);
      }
      return acc;
    }

    acc.push(line);
    return acc;
  }, []);

  output = 'CAVEMAN MODE ACTIVE — level: ' + modeLabel + '\n\n' + filtered.join('\n');
} else {
  // Fallback when SKILL.md is not found (standalone hook install without skills dir).
  // This is the minimum viable ruleset — better than nothing.
  output =
    'CAVEMAN MODE ACTIVE — level: ' + modeLabel + '\n\n' +
    'Respond terse like smart caveman. All technical substance stay. Only fluff die.\n\n' +
    '## Persistence\n\n' +
    'Default style for this whole session, every response, until user say "stop caveman" or "normal mode". Keep terse on long sessions — no filler drift.\n\n' +
    'Current level: **' + modeLabel + '**. Switch: `/caveman lite|full|ultra|wenyan-lite|wenyan-full|wenyan-ultra`.\n\n' +
    '## Rules\n\n' +
    'Drop: articles (a/an/the), filler (just/really/basically/actually/simply), pleasantries (sure/certainly/of course/happy to), hedging. ' +
    'Fragments OK. Short synonyms (big not extensive, fix not "implement a solution for"). Technical terms exact. Code blocks unchanged. Errors quoted exact.\n\n' +
    "Preserve user's dominant language. User write Portuguese → reply Portuguese caveman. Compress the style, not the language. Technical terms, code, API names, commands, error strings stay verbatim.\n\n" +
    'Answer directly in this style. Skip "caveman mode on" tags or a "Caveman:" recap — redundant with the reply itself.\n\n' +
    'Pattern: `[thing] [action] [reason]. [next step].`\n\n' +
    'Not: "Sure! I\'d be happy to help you with that. The issue you\'re experiencing is likely caused by..."\n' +
    'Yes: "Bug in auth middleware. Token expiry check use `<` not `<=`. Fix:"\n\n' +
    '## Auto-Clarity\n\n' +
    'Drop caveman for: security warnings, irreversible action confirmations, multi-step sequences where fragment order risks misread, user asks to clarify or repeats question. Resume caveman after clear part done.\n\n' +
    '## Boundaries\n\n' +
    'Code/commits/PRs: write normal. "stop caveman" or "normal mode": revert. Level persist until changed or session end.';
}

// 3. Detect missing statusline config — nudge Claude to help set it up.
// One-shot (#661): the nudge costs ~90 tokens per session, so a marker file
// gates it to the first session only. Users who declined stop paying for it.
const nudgeMarkerPath = path.join(claudeDir, '.caveman-nudge-shown');
try {
  let hasStatusline = false;
  if (fs.existsSync(settingsPath)) {
    const rawSettings = fs.readFileSync(settingsPath, 'utf8');
    try {
      hasStatusline = !!JSON.parse(rawSettings).statusLine;
    } catch (e) {
      // JSONC (comments / trailing commas) is legal in settings.json and the
      // hooks dir has no JSONC parser. Fall back to a substring probe and err
      // toward NOT nudging: a spurious "set up your statusline" for a user who
      // already has one is worse than a missing nudge.
      hasStatusline = rawSettings.includes('"statusLine"');
    }
  }

  if (!hasStatusline && !fs.existsSync(nudgeMarkerPath)) {
    safeWriteFlag(nudgeMarkerPath, '1');
    const isWindows = process.platform === 'win32';
    const scriptName = isWindows ? 'caveman-statusline.ps1' : 'caveman-statusline.sh';
    const scriptPath = path.join(__dirname, scriptName);
    const command = isWindows
      ? `powershell -ExecutionPolicy Bypass -File "${scriptPath}"`
      : `bash "${scriptPath}"`;
    const statusLineSnippet =
      '"statusLine": { "type": "command", "command": ' + JSON.stringify(command) + ' }';
    output += "\n\n" +
      "STATUSLINE SETUP NEEDED: The caveman plugin includes a statusline badge showing active mode " +
      "(e.g. [CAVEMAN], [CAVEMAN:ULTRA]). It is not configured yet. " +
      "To enable, add this to " + path.join(claudeDir, 'settings.json') + ": " +
      statusLineSnippet + " " +
      "Proactively offer to set this up for the user on first interaction.";
  }
} catch (e) {
  // Silent fail — don't block session start over statusline detection
}

process.stdout.write(output);
} // end run()

#!/usr/bin/env node
// caveman — shared configuration resolver
//
// KEEP THIS FILE LOADABLE WITHOUT THE MODULE LOADER. `src/plugins/opencode/
// plugin.js` cannot `require()` a file from disk (compiled Bun binary), so it
// reads this file's source and evaluates it through `new Function(...)` with a
// `createRequire` rooted at this file. Node built-ins (fs/path/os) resolve
// there; anything heavier does not. Consequence for mode-state work: keep it
// HERE. Parsing already lives in caveman-parse.js (#602) and is loaded the same
// way, so a second parser copy is no longer a risk — but a THIRD home for the
// state primitives would be, because opencode would keep its own drifting
// version of them (the drift #602 was created to end).
//
// Resolution order for default mode:
//   1. CAVEMAN_DEFAULT_MODE environment variable
//   2. Repo-local config (checked-in, per-project default):
//      - <cwd>/.caveman/config.json
//      - <cwd>/.caveman.json
//      Walks up from process.cwd() to the nearest ancestor containing one of
//      these (stops at filesystem root). Lets a team pin a project's default
//      mode without polluting every contributor's user-level config or env.
//   3. User config file defaultMode field:
//      - $XDG_CONFIG_HOME/caveman/config.json (any platform, if set)
//      - ~/.config/caveman/config.json (macOS / Linux fallback)
//      - %APPDATA%\caveman\config.json (Windows fallback)
//   4. 'full'

const fs = require('fs');
const path = require('path');
const os = require('os');

const VALID_MODES = [
  'off', 'lite', 'full', 'ultra',
  'wenyan-lite', 'wenyan', 'wenyan-full', 'wenyan-ultra',
  'commit', 'review', 'compress'
];

// Legacy machine-wide flag. Kept as a last-write-wins MIRROR of whichever
// session wrote most recently, because INSTALL.md tells users to `cat` it and
// src/hooks/README.md ships a third-party statusline snippet that reads it.
// It never receives the literal string 'off' — see writeSessionMode.
const FLAG_BASENAME = '.caveman-active';
const PREV_BASENAME = '.caveman-active.prev';

// Per-session state lives here, one small file per session id. Dot-prefixed to
// match the rest of the caveman namespace in $CLAUDE_CONFIG_DIR and to avoid
// colliding with Claude Code's own directories (projects/, hooks/, ...).
const SESSIONS_DIRNAME = '.caveman-sessions';

function getConfigDir() {
  if (process.env.XDG_CONFIG_HOME) {
    return path.join(process.env.XDG_CONFIG_HOME, 'caveman');
  }
  if (process.platform === 'win32') {
    return path.join(
      process.env.APPDATA || path.join(os.homedir(), 'AppData', 'Roaming'),
      'caveman'
    );
  }
  return path.join(os.homedir(), '.config', 'caveman');
}

function getConfigPath() {
  return path.join(getConfigDir(), 'config.json');
}

// Walk up from `start` looking for a repo-local caveman config. Returns the
// absolute path of the first match, or null. Stops at the filesystem root.
// Candidates per dir (first wins): .caveman/config.json, .caveman.json.
//
// Bounded to 64 levels to defend against symlink cycles on pathological mounts.
function findRepoConfigPath(start) {
  try {
    let dir = path.resolve(start || process.cwd());
    const candidates = ['.caveman/config.json', '.caveman.json'];
    for (let i = 0; i < 64; i++) {
      for (const rel of candidates) {
        const p = path.join(dir, rel);
        try {
          const st = fs.lstatSync(p);
          // Refuse symlinks — symmetric with safeWriteFlag/readFlag policy.
          if (st.isSymbolicLink() || !st.isFile()) continue;
          return p;
        } catch (e) {
          // not present, try next candidate
        }
      }
      const parent = path.dirname(dir);
      if (parent === dir) return null;
      dir = parent;
    }
  } catch (e) {
    // Defensive: any cwd / fs failure → no repo config
  }
  return null;
}

function readModeFromConfigFile(configPath) {
  try {
    const raw = fs.readFileSync(configPath, 'utf8');
    const config = JSON.parse(raw);
    if (config && config.defaultMode &&
        VALID_MODES.includes(String(config.defaultMode).toLowerCase())) {
      return String(config.defaultMode).toLowerCase();
    }
  } catch (e) {
    // Missing / unreadable / invalid JSON → caller falls through
  }
  return null;
}

// startDir overrides the cwd the repo-config walk starts from (default
// process.cwd(), same as findRepoConfigPath's own fallback) — lets a caller
// resolve the mode for a directory other than its own process cwd (#634:
// the UserPromptSubmit hook's stdin carries the session's cwd, which can
// differ from the hook process's cwd). Every other resolution step is
// cwd-independent, so only the repo-config walk takes it.
function getDefaultMode(startDir) {
  // 1. Environment variable (highest priority)
  const envMode = process.env.CAVEMAN_DEFAULT_MODE;
  if (envMode && VALID_MODES.includes(envMode.toLowerCase())) {
    return envMode.toLowerCase();
  }

  // 2. Repo-local config (checked-in, per-project default)
  const repoConfigPath = findRepoConfigPath(startDir);
  if (repoConfigPath) {
    const repoMode = readModeFromConfigFile(repoConfigPath);
    if (repoMode) return repoMode;
  }

  // 3. User config file
  const userMode = readModeFromConfigFile(getConfigPath());
  if (userMode) return userMode;

  // 4. Default
  return 'full';
}

// Symlink-safe flag file write.
// Uses O_NOFOLLOW where available, writes atomically via temp + rename with
// 0600 permissions. Protects against local attackers replacing the predictable
// flag path (~/.claude/.caveman-active) with a symlink to clobber other files.
//
// When the parent directory is itself a symlink (legitimate pattern: ~/.claude
// symlinked to another drive or shared config dir), resolves through to the
// real path and verifies ownership on Unix (uid match). This allows e.g.
//   ln -s /opt/shared-claude-config ~/.claude
// while still refusing attacker-planted symlinks pointing to dirs owned by
// another user.
//
// On Windows, uid checks are unavailable — falls back to verifying the resolved
// path lives under the user's home directory.
//
// The flag file itself must never be a symlink (that's the actual clobber vector).
//
// Set CAVEMAN_DEBUG=1 to emit stderr diagnostics when flag writes are refused.
//
// Silent-fails on any filesystem error — the flag is best-effort.
// Blocking sleep with no child process and no busy-wait. Used only to space
// out rename retries under Windows lock contention.
function sleepMs(ms) {
  try {
    Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms);
  } catch (e) { /* SharedArrayBuffer unavailable — skip the backoff */ }
}

function safeWriteFlag(flagPath, content) {
  const debug = process.env.CAVEMAN_DEBUG === '1';
  try {
    const flagDir = path.dirname(flagPath);
    fs.mkdirSync(flagDir, { recursive: true });

    // When the parent directory is a symlink, resolve it and verify ownership.
    // This allows legitimate symlinked ~/.claude dirs while still refusing
    // attacker-planted symlinks pointing at dirs owned by another user.
    let realFlagDir;
    try {
      const lstat = fs.lstatSync(flagDir);
      if (lstat.isSymbolicLink()) {
        realFlagDir = fs.realpathSync(flagDir);
        const realStat = fs.statSync(realFlagDir);
        if (!realStat.isDirectory()) {
          if (debug) process.stderr.write(`[caveman] safeWriteFlag: symlink target ${realFlagDir} is not a directory\n`);
          return;
        }
        if (typeof process.getuid === 'function') {
          if (realStat.uid !== process.getuid()) {
            if (debug) process.stderr.write(`[caveman] safeWriteFlag: symlink target ${realFlagDir} owned by uid ${realStat.uid}, not current user ${process.getuid()}\n`);
            return;
          }
        } else {
          const home = os.homedir();
          const normalizedReal = path.resolve(realFlagDir);
          const normalizedHome = path.resolve(home);
          if (!normalizedReal.toLowerCase().startsWith(normalizedHome.toLowerCase() + path.sep) &&
              normalizedReal.toLowerCase() !== normalizedHome.toLowerCase()) {
            if (debug) process.stderr.write(`[caveman] safeWriteFlag: symlink target ${normalizedReal} is outside home directory ${normalizedHome}\n`);
            return;
          }
        }
      } else {
        realFlagDir = flagDir;
      }
    } catch (e) {
      return;
    }

    // The flag file itself must never be a symlink (that's the actual clobber vector).
    const realFlagPath = path.join(realFlagDir, path.basename(flagPath));
    try {
      if (fs.lstatSync(realFlagPath).isSymbolicLink()) return;
    } catch (e) {
      if (e.code !== 'ENOENT') return;
    }

    // tempPath is hoisted above the try so the finally below can always find
    // it. On Windows, renameSync onto an existing target throws EPERM/EBUSY/
    // EACCES/EEXIST when another process (statusline read, a concurrent
    // session's hook) holds the file open without FILE_SHARE_DELETE —
    // without the retry + guaranteed cleanup here, every such miss left an
    // orphaned .caveman-active.<pid>.<ts> file behind (#511/#578/#657).
    let tempPath;
    try {
      tempPath = path.join(realFlagDir, `.caveman-active.${process.pid}.${Date.now()}`);
      const O_NOFOLLOW = typeof fs.constants.O_NOFOLLOW === 'number' ? fs.constants.O_NOFOLLOW : 0;
      const flags = fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_EXCL | O_NOFOLLOW;
      let fd;
      try {
        fd = fs.openSync(tempPath, flags, 0o600);
        fs.writeSync(fd, String(content));
        try { fs.fchmodSync(fd, 0o600); } catch (e) { /* best-effort on Windows */ }
      } finally {
        if (fd !== undefined) fs.closeSync(fd);
      }

      // Retry brief lock contention a few times, backing off between attempts.
      // Three synchronous attempts with no delay all complete inside a few
      // microseconds, so whichever handle blocked the first (a statusline read,
      // a concurrent session's hook, an AV scan) is still held for the other
      // two — effectively one attempt with two extra syscalls. Sleep for real:
      // Atomics.wait blocks this thread without pulling in a child process,
      // which is what a hook budget can least afford.
      let renamed = false;
      for (let attempt = 0; attempt < 3; attempt++) {
        try {
          fs.renameSync(tempPath, realFlagPath);
          renamed = true;
          break;
        } catch (e) {
          const transient = e.code === 'EPERM' || e.code === 'EBUSY' ||
                             e.code === 'EACCES' || e.code === 'EEXIST';
          if (!transient) throw e;
          if (attempt < 2) sleepMs(10 * (attempt + 1));
        }
      }
      if (!renamed && debug) {
        process.stderr.write('[caveman] safeWriteFlag: rename contended after 3 attempts; flag not updated this write\n');
      }
    } finally {
      if (tempPath) {
        try {
          fs.unlinkSync(tempPath);
        } catch (error) {
          if (debug && error.code !== 'ENOENT') {
            process.stderr.write(`[caveman] safeWriteFlag: failed to remove temp flag ${tempPath}: ${error.message}\n`);
          }
        }
      }
    }
  } catch (e) {
    // Silent fail — flag is best-effort
  }
}

// Symlink-safe, size-capped, whitelist-validated flag file read.
// Symmetric with safeWriteFlag: refuses symlinks at the target, caps the read,
// and rejects anything that isn't a known mode. Returns null on any anomaly.
//
// Without this, a local attacker with write access to ~/.claude/ could replace
// the flag with a symlink to ~/.ssh/id_rsa (or any user-readable secret). Every
// reader — statusline, per-turn reinforcement — would slurp that content and
// either echo it to the terminal or inject it into model context.
//
// MAX_FLAG_BYTES is a hard cap. The longest legitimate value is "wenyan-ultra"
// (12 bytes); 64 leaves slack without enabling exfil.
const MAX_FLAG_BYTES = 64;

function readFlag(flagPath) {
  try {
    let st;
    try {
      st = fs.lstatSync(flagPath);
    } catch (e) {
      return null;
    }
    if (st.isSymbolicLink() || !st.isFile()) return null;
    if (st.size > MAX_FLAG_BYTES) return null;

    const O_NOFOLLOW = typeof fs.constants.O_NOFOLLOW === 'number' ? fs.constants.O_NOFOLLOW : 0;
    const flags = fs.constants.O_RDONLY | O_NOFOLLOW;
    let fd;
    let out;
    try {
      fd = fs.openSync(flagPath, flags);
      const buf = Buffer.alloc(MAX_FLAG_BYTES);
      const n = fs.readSync(fd, buf, 0, MAX_FLAG_BYTES, 0);
      out = buf.slice(0, n).toString('utf8');
    } finally {
      if (fd !== undefined) fs.closeSync(fd);
    }

    const raw = out.trim().toLowerCase();
    if (!VALID_MODES.includes(raw)) return null;
    return raw;
  } catch (e) {
    return null;
  }
}

// Symlink-safe append. Same parent-dir + symlink-target rules as safeWriteFlag,
// but opens with O_APPEND so concurrent writers from different sessions don't
// clobber each other. Used for the lifetime stats log
// ($CLAUDE_CONFIG_DIR/.caveman-history.jsonl).
//
// Silent-fails on any filesystem error.
function appendFlag(filePath, line) {
  const debug = process.env.CAVEMAN_DEBUG === '1';
  try {
    const dir = path.dirname(filePath);
    fs.mkdirSync(dir, { recursive: true });

    let realDir;
    try {
      const lstat = fs.lstatSync(dir);
      if (lstat.isSymbolicLink()) {
        realDir = fs.realpathSync(dir);
        const realStat = fs.statSync(realDir);
        if (!realStat.isDirectory()) return;
        if (typeof process.getuid === 'function') {
          if (realStat.uid !== process.getuid()) {
            if (debug) process.stderr.write(`[caveman] appendFlag: symlink target ${realDir} owned by uid ${realStat.uid}\n`);
            return;
          }
        } else {
          const home = os.homedir();
          const normalized = path.resolve(realDir).toLowerCase();
          const normalizedHome = path.resolve(home).toLowerCase();
          if (!normalized.startsWith(normalizedHome + path.sep) && normalized !== normalizedHome) return;
        }
      } else {
        realDir = dir;
      }
    } catch (e) {
      return;
    }

    const realPath = path.join(realDir, path.basename(filePath));
    try {
      if (fs.lstatSync(realPath).isSymbolicLink()) return;
    } catch (e) {
      if (e.code !== 'ENOENT') return;
    }

    const O_NOFOLLOW = typeof fs.constants.O_NOFOLLOW === 'number' ? fs.constants.O_NOFOLLOW : 0;
    const flags = fs.constants.O_WRONLY | fs.constants.O_CREAT | fs.constants.O_APPEND | O_NOFOLLOW;
    let fd;
    try {
      fd = fs.openSync(realPath, flags, 0o600);
      fs.writeSync(fd, String(line).replace(/\n$/, '') + '\n');
      try { fs.fchmodSync(fd, 0o600); } catch (e) { /* best-effort on Windows */ }
    } finally {
      if (fd !== undefined) fs.closeSync(fd);
    }
  } catch (e) {
    // Silent fail — history is best-effort
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// Per-session mode state
//
// The mode is applied per session but used to be stored in ONE file per
// machine. That single fact caused four bugs: parallel sessions shared a mode,
// SessionStart re-derived the default and clobbered an explicit "stop caveman"
// after every auto-compaction, the statusline badge showed the same mode in
// every window, and "off" — expressed as file ABSENCE — could never survive a
// SessionStart.
//
// #691 fixed the compaction case for a mid-session LEVEL change by branching on
// the hook payload's `source`. It cannot fix the other three, because all of
// them are consequences of the storage shape rather than of when the hook
// re-derives: one file cannot hold two windows' modes, and an absent file
// cannot express "deliberately off" distinguishably from "never set".
//
// Storage: $CLAUDE_CONFIG_DIR/.caveman-sessions/<session_id>.mode (+ .prev),
// with the legacy flag kept as a compat mirror.
//
// Every function below accepts a sessionId that may be null or malformed and
// degrades to the previous machine-wide behavior in that case. That is the
// whole backward-compatibility story: the old code path IS the fallback
// branch, so a caller with no session id behaves exactly as it did before.
// ─────────────────────────────────────────────────────────────────────────────

// A session id becomes part of a filesystem path, so it is a path-traversal
// vector. Whitelist the alphabet rather than blacklisting separators — same
// philosophy as VALID_MODES. Claude Code sends a UUID, but the regex stays
// deliberately broad so a future id format degrades to the legacy path instead
// of throwing. Length-capped so a hostile id cannot blow past filename limits.
const SESSION_ID_RE = /^[A-Za-z0-9_-]{1,128}$/;

function validateSessionId(id) {
  if (typeof id !== 'string' || !SESSION_ID_RE.test(id)) return null;
  return id;
}

function legacyFlagPath(claudeDir) {
  return path.join(claudeDir, FLAG_BASENAME);
}

function sessionsDir(claudeDir) {
  return path.join(claudeDir, SESSIONS_DIRNAME);
}

// Returns null for any id the whitelist rejects. The resolved-path containment
// check is redundant while SESSION_ID_RE holds, but it is cheap and it defends
// against a future edit loosening the regex — the same defense-in-depth style
// as the symlink checks in safeWriteFlag.
function sessionStatePath(claudeDir, sessionId, ext) {
  const sid = validateSessionId(sessionId);
  if (!sid) return null;
  const dir = sessionsDir(claudeDir);
  const candidate = path.join(dir, sid + ext);
  if (path.dirname(path.resolve(candidate)) !== path.resolve(dir)) return null;
  return candidate;
}

function sessionActivePath(claudeDir, sessionId) {
  return sessionStatePath(claudeDir, sessionId, '.mode');
}

function sessionPrevPath(claudeDir, sessionId) {
  return sessionStatePath(claudeDir, sessionId, '.prev');
}

// Both "no file" and the literal 'off' mean caveman is off. Collapsing them to
// a single null is what implements the dual-read compat requirement: a missing
// file is the old spelling, a literal 'off' the new durable one.
function offToNull(mode) {
  return (!mode || mode === 'off') ? null : mode;
}

// "What mode is in effect right now" — for every reader (per-turn
// reinforcement gate, ruleset re-emission, statusline, stats).
function resolveActiveMode(claudeDir, sessionId) {
  const sessionPath = sessionActivePath(claudeDir, sessionId);
  if (sessionPath) {
    const stored = readFlag(sessionPath);
    if (stored !== null) return offToNull(stored);
  }
  return offToNull(readFlag(legacyFlagPath(claudeDir)));
}

// "What is literally written for THIS session" — no legacy fallback, and 'off'
// comes back verbatim. Two callers need exactly this: recordModeChange (whose
// comparison against the shared mirror would diff against whatever some OTHER
// session wrote last and spam the log with phantom transitions) and the
// SessionStart continuation branch, which has to tell "this session chose off"
// apart from "this session has no state yet".
function readSessionModeRaw(claudeDir, sessionId) {
  const sessionPath = sessionActivePath(claudeDir, sessionId);
  if (!sessionPath) return readFlag(legacyFlagPath(claudeDir));
  return readFlag(sessionPath);
}

// Single writer for the active mode. Pass null (or 'off') to deactivate.
//
// The session file stores 'off' literally — that is what makes deactivation
// durable across SessionStart. The legacy mirror instead gets UNLINKED, and
// never holds the literal 'off', on purpose: 'off' is already in VALID_MODES,
// so an older caveman-mode-tracker.js reading it from the legacy path would
// clear its !INDEPENDENT_MODES check and inject "CAVEMAN MODE ACTIVE (off)",
// and an older caveman-statusline.sh would render [CAVEMAN:OFF] instead of
// staying silent. Mixed-version installs are real — plugin hooks and
// standalone hooks can both be registered, and settings.json holds a
// statusline path baked in at install time.
function writeSessionMode(claudeDir, sessionId, modeOrNull) {
  const canonical = (!modeOrNull || modeOrNull === 'off') ? 'off' : modeOrNull;
  if (!VALID_MODES.includes(canonical)) return;

  const sessionPath = sessionActivePath(claudeDir, sessionId);
  if (sessionPath) safeWriteFlag(sessionPath, canonical);

  const legacy = legacyFlagPath(claudeDir);
  if (canonical === 'off') {
    try { fs.unlinkSync(legacy); } catch (e) { /* already absent */ }
  } else {
    safeWriteFlag(legacy, canonical);
  }
}

// Displaced-prose-mode memory for one-shot independent modes (#599), scoped to
// the session. Without the scoping, two windows each running /caveman-commit
// would overwrite each other's "where to return to".
//
// Unlike the active mode, prev is stored in EXACTLY ONE place — the session
// file when there is a valid session id, the legacy file otherwise. It is not
// mirrored, and the read/clear helpers must not cross that line either.
//
// Falling back to the legacy prev whenever a session simply has none of its own
// is a real bug, not a convenience: a session where caveman was never on saves
// no prev (there is nothing to displace), so after /caveman-commit it would
// restore from whatever stale machine-wide prev another context left behind and
// switch itself on at that mode. Symmetrically, clearing must not reach across
// and delete machine-wide state on behalf of one session.
function writeSessionPrev(claudeDir, sessionId, mode) {
  if (!mode || !VALID_MODES.includes(mode)) return;
  const p = sessionPrevPath(claudeDir, sessionId) || path.join(claudeDir, PREV_BASENAME);
  safeWriteFlag(p, mode);
}

function readSessionPrev(claudeDir, sessionId) {
  const p = sessionPrevPath(claudeDir, sessionId);
  if (p) return readFlag(p);
  return readFlag(path.join(claudeDir, PREV_BASENAME));
}

function clearSessionPrev(claudeDir, sessionId) {
  const p = sessionPrevPath(claudeDir, sessionId);
  if (p) {
    try { fs.unlinkSync(p); } catch (e) {}
    return;
  }
  try { fs.unlinkSync(path.join(claudeDir, PREV_BASENAME)); } catch (e) {}
}

// Sweep stale per-session files. Called from SessionStart on a genuinely new
// session only — not on every compaction, which is frequent in a long session
// and would spend the 5s hook budget on directory walks.
//
// maxDeletes caps the first sweep on a machine that already accumulated many
// sessions. TTL is overridable via env so tests need not fake two weeks.
const SESSION_TTL_MS = 14 * 24 * 60 * 60 * 1000;

function gcSessionStore(claudeDir, opts) {
  const options = opts || {};
  const envTtl = Number(process.env.CAVEMAN_SESSION_TTL_MS);
  const maxAgeMs = options.maxAgeMs
    || (Number.isFinite(envTtl) && envTtl > 0 ? envTtl : SESSION_TTL_MS);
  const maxDeletes = options.maxDeletes || 500;

  try {
    const dir = sessionsDir(claudeDir);
    const entries = fs.readdirSync(dir);
    const cutoff = Date.now() - maxAgeMs;
    let deleted = 0;
    for (const name of entries) {
      if (deleted >= maxDeletes) break;
      const p = path.join(dir, name);
      try {
        const st = fs.lstatSync(p);
        // Refuse symlinks rather than following them into someone else's file.
        if (st.isSymbolicLink() || !st.isFile()) continue;
        if (st.mtimeMs < cutoff) { fs.unlinkSync(p); deleted++; }
      } catch (e) { /* vanished or unreadable — skip */ }
    }
    return deleted;
  } catch (e) {
    // Missing directory (fresh install) or any fs failure — nothing to do.
    return 0;
  }
}

// Mode-transition log (#601). Whenever the active mode actually changes,
// append {ts, mode, prev, session_id} to
// $CLAUDE_CONFIG_DIR/.caveman-mode-log.jsonl so caveman-stats can attribute
// output tokens to the mode that was active when each message was generated,
// instead of whatever mode the flag holds at stats time. mode/prev are a
// VALID_MODES string or null (null = caveman off). prev lets stats attribute
// messages that predate the first logged transition of a session. No-op when
// the mode is unchanged; best-effort like all flag IO.
//
// session_id is omitted (not null) when unknown, so JSON.stringify drops the
// key and readers written before this field existed see the old shape.
const MODE_LOG_BASENAME = '.caveman-mode-log.jsonl';

// Normalizing through offToNull before comparing matters here: without it a
// durable-off write looks like a transition from 'off' to null and lands a
// phantom entry in the log — and attributing output tokens to a mode named
// 'off' would be meaningless besides.
function recordModeChange(claudeDir, newMode, sessionId) {
  try {
    const current = offToNull(readSessionModeRaw(claudeDir, sessionId));
    const next = offToNull(newMode);
    if (current === next) return;
    const entry = { ts: Date.now(), mode: next, prev: current };
    const sid = validateSessionId(sessionId);
    if (sid) entry.session_id = sid;
    appendFlag(path.join(claudeDir, MODE_LOG_BASENAME), JSON.stringify(entry));
  } catch (e) {
    // Silent fail — the log is best-effort
  }
}

// Symlink-safe history read. Returns lines (untrimmed) or empty array on any
// anomaly. Caller is responsible for parsing JSON. Does NOT enforce a size cap
// the way readFlag does — history is expected to grow with use.
function readHistory(filePath) {
  try {
    const st = fs.lstatSync(filePath);
    if (st.isSymbolicLink() || !st.isFile()) return [];
    const O_NOFOLLOW = typeof fs.constants.O_NOFOLLOW === 'number' ? fs.constants.O_NOFOLLOW : 0;
    const flags = fs.constants.O_RDONLY | O_NOFOLLOW;
    let fd;
    let raw;
    try {
      fd = fs.openSync(filePath, flags);
      raw = fs.readFileSync(fd, 'utf8');
    } finally {
      if (fd !== undefined) fs.closeSync(fd);
    }
    return raw.split('\n').filter(line => line.trim());
  } catch (e) {
    return [];
  }
}

module.exports = {
  getDefaultMode, getConfigDir, getConfigPath, findRepoConfigPath, VALID_MODES,
  safeWriteFlag, readFlag, appendFlag, readHistory,
  recordModeChange, MODE_LOG_BASENAME,
  // Per-session state
  SESSIONS_DIRNAME, FLAG_BASENAME, PREV_BASENAME,
  validateSessionId, legacyFlagPath, sessionsDir,
  sessionActivePath, sessionPrevPath,
  resolveActiveMode, readSessionModeRaw, writeSessionMode,
  writeSessionPrev, readSessionPrev, clearSessionPrev,
  gcSessionStore,
};

#!/usr/bin/env node
// caveman — UserPromptSubmit hook to track which caveman mode is active
// Inspects user input for /caveman commands and writes mode to flag file

const fs = require('fs');
const path = require('path');
const os = require('os');
const { execFileSync } = require('child_process');
// caveman-config.js and caveman-parse.js are mandatory siblings, but an
// incomplete install leaves one absent. A bare top-level require turns that
// into an uncaught MODULE_NOT_FOUND on EVERY prompt, which the harness
// surfaces only as an opaque loader stack trace (#848). Resolve defensively.
//
// Deliberately inlined rather than extracted into a shared helper: a shared
// loader would itself be one more sibling that can go missing, which is the
// exact failure this guards against.
function requireSibling(name, isUsable) {
  let mod;
  try {
    mod = require('./' + name);
  } catch (primary) {
    // The opencode install layout renames siblings to `.cjs` (its plugin dir
    // is "type": "module"), same fallback caveman-parse.js already does. Gate
    // the retry on the error naming THIS module: a MODULE_NOT_FOUND thrown by
    // a require *inside* a sibling that loaded fine must not be re-reported as
    // "./<name>.cjs is missing", blaming a file never meant to exist.
    const message = String((primary && primary.message) || primary);
    if (primary && primary.code === 'MODULE_NOT_FOUND' && message.includes("'./" + name + "'")) {
      try { return require('./' + name + '.cjs'); } catch (e) { /* report primary */ }
    }
    const absent = !fs.existsSync(path.join(__dirname, name + '.js'))
                && !fs.existsSync(path.join(__dirname, name + '.cjs'));
    // Distinguish "the sibling is absent" from "the sibling loaded but its own
    // require failed" — naming the wrong cause is worse than no message. Only
    // the first line of error.message: Node appends a multi-line "Require
    // stack:" block, the very noise this guard exists to remove.
    process.stderr.write('caveman: ' + (absent
      ? name + '.js is missing from ' + __dirname + ' — the install is incomplete.'
      : name + ' could not load — ' + message.split('\n')[0]) + '\n'
      + 'Run `/plugin update caveman`, or rerun install.sh for standalone hooks. '
      + 'Continuing with reduced functionality.\n');
    return null;
  }
  // A module that LOADS but exports the wrong shape is the plugin-cache-drift
  // case #848 describes. Without this check the first use dereferences
  // undefined — the raw stack trace this guard exists to remove.
  if (!isUsable(mod)) {
    process.stderr.write('caveman: ' + name + ' loaded but is missing expected exports — the install is inconsistent.\n'
      + 'Run `/plugin update caveman`, or rerun install.sh for standalone hooks. '
      + 'Continuing with reduced functionality.\n');
    return null;
  }
  return mod;
}

// Degraded stubs make this hook a clean no-op when a sibling is unusable: no
// mode change is parsed, readFlag reports nothing active, so nothing is emitted
// and the process still exits 0 with stdin drained (never a broken pipe, #397).
// getDefaultMode's stub value is never consulted in that state — the only call
// site is gated behind an activeMode that readFlag can no longer produce.
const cavemanConfig = requireSibling('caveman-config', (m) =>
  m && typeof m.getDefaultMode === 'function' && typeof m.safeWriteFlag === 'function'
    && typeof m.readFlag === 'function' && typeof m.recordModeChange === 'function'
    && Array.isArray(m.VALID_MODES));
const { getDefaultMode, safeWriteFlag, readFlag, recordModeChange, VALID_MODES } = cavemanConfig || {
  getDefaultMode: () => 'full',
  safeWriteFlag: () => {},
  readFlag: () => null,
  recordModeChange: () => {},
  VALID_MODES: [],
};

// Per-session helpers, resolved individually rather than folded into the shape
// check above: a caveman-config.js from before per-session state satisfies that
// check, and failing the whole module over the newer exports would turn "mode
// still tracked, machine-wide" into "hook is a no-op". Each stub reproduces the
// pre-per-session behavior against the legacy flag instead.
const cfg = cavemanConfig || {};
const validateSessionId = cfg.validateSessionId || (() => null);
const resolveActiveMode = cfg.resolveActiveMode || (() => {
  const m = readFlag(flagPath);
  return (!m || m === 'off') ? null : m;
});
const writeSessionMode = cfg.writeSessionMode || ((dir, sid, modeOrNull) => {
  if (!modeOrNull || modeOrNull === 'off') removeFlag(flagPath);
  else safeWriteFlag(flagPath, modeOrNull);
});
const writeSessionPrev = cfg.writeSessionPrev || ((dir, sid, mode) => safeWriteFlag(prevPath, mode));
const readSessionPrev = cfg.readSessionPrev || (() => readFlag(prevPath));
const clearSessionPrev = cfg.clearSessionPrev || (() => removeFlag(prevPath));
const { parseModeChange, INDEPENDENT_MODES } = requireSibling('caveman-parse', (m) =>
  m && typeof m.parseModeChange === 'function' && m.INDEPENDENT_MODES instanceof Set) || {
  parseModeChange: () => null,
  INDEPENDENT_MODES: new Set(['commit', 'review', 'compress']),
};

const claudeDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
const flagPath = path.join(claudeDir, '.caveman-active');
// Remembers the prose mode active before a one-shot independent mode
// (/caveman-commit etc.) so the next ordinary prompt can restore it (#599).
const prevPath = path.join(claudeDir, '.caveman-active.prev');

function removeFlag(path) {
  try {
    fs.unlinkSync(path);
  } catch (error) {
    if (process.env.CAVEMAN_DEBUG === '1' && error.code !== 'ENOENT') {
      console.error(`caveman: failed to remove flag ${path}: ${error.message}`);
    }
  }
}

let input = '';
let handled = false;

// Act on the first COMPLETE JSON payload rather than waiting for EOF. The host
// writes one object and closes, but under the Windows pipe implementation that
// close can lag arbitrarily (#729/#833) — and this hook is registered with a 5s
// budget, so a lagging EOF spends the whole budget and the host kills us before
// the flag is ever written. Parsing per chunk costs one JSON.parse of a payload
// we are about to parse anyway.
function handle(raw) {
  if (handled) return;
  handled = true;
  try {
    const data = JSON.parse(raw);

    // Scopes every read and write below to this session. null when absent or
    // malformed, in which case the helpers above fall back to the legacy
    // machine-wide flag — i.e. exactly the pre-per-session behavior.
    const sessionId = validateSessionId(data.session_id);

    // Collapse whitespace so phrase triggers still match multiline prompts —
    // every regex below sees a single-line prompt (#598).
    let prompt = (data.prompt || '').trim().toLowerCase().replace(/\s+/g, ' ');

    // Unattended scheduled-task runs must never receive caveman styling —
    // the per-turn reinforcement would hijack the task prompt, and a
    // lightweight scheduled task would answer with a caveman greeting
    // instead of doing its job. Claude Code wraps these in a
    // <scheduled-task ...> marker; bail out completely when present: no flag
    // mutation, no reinforcement, no stats. Interactive sessions are
    // unaffected.
    if (/<scheduled-task\b/.test(prompt)) return;

    // Claude Code delivers slash commands to this hook as an envelope, not
    // the literal command (#537):
    //   <command-message>caveman</command-message>
    //   <command-name>/caveman</command-name>
    //   <command-args>ultra</command-args>
    // (one-line or newline-separated — the collapse above normalizes both
    // into single spaces; <command-args> may be empty or absent). Every
    // switch below matches against the literal command string, so this
    // envelope was a silent no-op for every slash command, including
    // '/caveman off'. Reconstruct '<name> <args>' for /caveman* envelopes so
    // the rest of this hook sees exactly what the user selected. A foreign
    // command's envelope is left untouched, and natural-language detection
    // is skipped for it so another command's own args can't misfire our
    // activation/deactivation triggers.
    let skipNaturalLanguage = false;
    const envName = /<command-name>\s*([^<\s]+)\s*<\/command-name>/.exec(prompt);
    if (envName) {
      if (envName[1].startsWith('/caveman')) {
        const envArgs = /<command-args>\s*([^<]*?)\s*<\/command-args>/.exec(prompt);
        const args = envArgs ? envArgs[1].trim() : '';
        prompt = args ? envName[1] + ' ' + args : envName[1];
      } else {
        skipNaturalLanguage = true;
      }
    }

    // /caveman-stats [--share] — run the stats script and inject its output
    // as additionalContext (#618), instructing the model to relay it
    // verbatim. The script reads the active session log, so we pass
    // transcript_path through when Claude Code provides it.
    const statsMatch = /^\/caveman(?::caveman)?-stats(?:\s+(.*))?$/.exec(prompt);
    if (statsMatch) {
      const tailArgs = (statsMatch[1] || '').trim().split(/\s+/).filter(Boolean);
      let block;
      try {
        const statsPath = path.join(__dirname, 'caveman-stats.js');
        const argv = [statsPath];
        if (data.transcript_path) argv.push('--session-file', data.transcript_path);
        // Lets stats drop mode-log rows belonging to other windows instead of
        // joining them onto this session's timeline.
        if (sessionId) argv.push('--session-id', sessionId);
        if (tailArgs.includes('--share')) argv.push('--share');
        if (tailArgs.includes('--all')) argv.push('--all');
        const sinceIdx = tailArgs.indexOf('--since');
        if (sinceIdx !== -1 && tailArgs[sinceIdx + 1]) {
          argv.push('--since', tailArgs[sinceIdx + 1]);
        }
        // 2.5s. Hook registration allows 30s for slow Windows process startup,
        // while this child watchdog still bounds optional context loading.
        // already spent its own Node startup; giving the child the host's
        // entire budget means the host kills the hook before the child's own
        // timeout can fire and produce the fallback message. Windows process
        // spawn is ~10x macOS before antivirus (#819), so the margin is real.
        block = execFileSync(process.execPath, argv, { encoding: 'utf8', timeout: 2500 }).trim();
      } catch (e) {
        block = 'caveman-stats: could not run stats script.\nTry manually: node hooks/caveman-stats.js';
      }
      process.stdout.write(JSON.stringify({
        hookSpecificOutput: {
          hookEventName: "UserPromptSubmit",
          additionalContext: 'Print this stats block verbatim inside a fenced code block. Say nothing else.\n\n' + block
        }
      }));
      return;
    }

    // Shared mode-change parser (#602) — single source of truth with the
    // opencode plugin for slash commands, namespaced /caveman:caveman-*,
    // natural-language activation/deactivation, and brevity triggers.
    const change = parseModeChange(prompt, { getDefaultMode, skipNaturalLanguage });

    // A /caveman argument that resolves to no mode used to leave the level
    // untouched and say nothing, so a typo or punctuation glued to the level
    // ("/caveman ultra;") looked like it worked. Build a notice instead — but
    // do NOT return here: an early exit would skip the #599 one-shot restore
    // below, stranding the user in /caveman-commit for an extra turn because
    // they made a typo, and would also drop that turn's reinforcement.
    let notice = null;
    if (change && change.action === 'unresolved') {
      if (change.independentMode) {
        // A real mode, just not reachable via /caveman <arg>. Denying it exists
        // would contradict the docs.
        notice = 'Tell the user ' + change.independentMode + ' mode is set with its own command, '
          + '/caveman-' + change.independentMode + ', not /caveman ' + change.independentMode
          + '. The level is unchanged.';
      } else {
        // Levels are derived from VALID_MODES so they cannot drift from the
        // parser, minus 'off', the independent modes, and 'wenyan' — that is
        // the storage alias for wenyan-full, and listing both would advertise
        // seven levels for a product documented as having six. The rejected
        // argument is never echoed: it is untrusted input headed for model
        // context.
        const levels = VALID_MODES.filter(m => m !== 'off' && m !== 'wenyan' && !INDEPENDENT_MODES.has(m));
        notice = 'Tell the user their /caveman level was not recognized and the level is '
          + 'unchanged. Valid levels: ' + levels.join(', ') + '. Use /caveman off to deactivate.';
      }
    }

    // Independent one-shot modes remember the prose mode active before them
    // so the next ordinary prompt restores it (#599) — SKILL.md promises
    // "Level persist until changed or session end", and a one-shot skill
    // invocation should not count as "changed" forever.
    let setIndependentThisTurn = false;
    if (change && change.action === 'set') {
      const mode = change.mode;
      if (INDEPENDENT_MODES.has(mode)) {
        // Save the prose mode being displaced — but never overwrite an
        // already-saved one with another independent mode (/caveman-commit
        // followed by /caveman-review must still restore the original).
        const current = resolveActiveMode(claudeDir, sessionId);
        if (current && !INDEPENDENT_MODES.has(current)) {
          writeSessionPrev(claudeDir, sessionId, current);
        }
        setIndependentThisTurn = true;
      }
      recordModeChange(claudeDir, mode, sessionId); // #601: timestamped transition log
      writeSessionMode(claudeDir, sessionId, mode);
    } else if (change && change.action === 'clear') {
      // Durable off: writeSessionMode stores the literal 'off' for this session
      // (and unlinks the legacy mirror), so the next SessionStart cannot mistake
      // deactivation for "never set" and re-arm caveman on the next compaction.
      recordModeChange(claudeDir, null, sessionId); // #601
      writeSessionMode(claudeDir, sessionId, null);
      clearSessionPrev(claudeDir, sessionId);
    }

    // Per-turn reinforcement: emit a short reminder when caveman is active.
    // The SessionStart hook injects the full ruleset once, but models lose it
    // when other plugins inject competing style instructions every turn.
    // This keeps caveman visible in the model's attention on every user message.
    //
    // Skip independent modes (commit, review, compress) — they have their own
    // skill behavior and the base caveman rules would conflict.
    // resolveActiveMode enforces symlink-safe read + size cap + VALID_MODES
    // whitelist, and treats both a missing file and a durable 'off' as "no
    // mode". If the state is missing, corrupted, oversized, or a symlink
    // pointing at something like ~/.ssh/id_rsa, it returns null and we emit
    // nothing — never inject untrusted bytes into model context.
    let activeMode = resolveActiveMode(claudeDir, sessionId);

    // One-shot restore (#599): an independent mode set on a PREVIOUS prompt
    // has served its turn — bring back the prose mode that was active before
    // it, or deactivate if caveman wasn't active then.
    if (activeMode && INDEPENDENT_MODES.has(activeMode) && !setIndependentThisTurn) {
      const prev = readSessionPrev(claudeDir, sessionId);
      clearSessionPrev(claudeDir, sessionId);
      // `prev !== 'off'` is not redundant: prev is stored literally, and
      // restoring a stored 'off' as a mode would inject "CAVEMAN MODE ACTIVE
      // (off)" for a session that had deliberately turned caveman off.
      if (prev && !INDEPENDENT_MODES.has(prev) && prev !== 'off') {
        recordModeChange(claudeDir, prev, sessionId); // #601
        writeSessionMode(claudeDir, sessionId, prev);
        activeMode = prev;
      } else {
        recordModeChange(claudeDir, null, sessionId); // #601
        writeSessionMode(claudeDir, sessionId, null);
        activeMode = null;
      }
    }

    // #634: a repo-local .caveman.json / .caveman/config.json can set
    // defaultMode "off" to opt a project out of caveman entirely. Thread the
    // hook stdin's cwd through so that check resolves for the session's
    // directory, not this hook process's own cwd. This gates ONLY the
    // reinforcement output below — it never deletes or writes the flag file.
    const reinforce = activeMode && !INDEPENDENT_MODES.has(activeMode)
      && getDefaultMode(data.cwd) !== 'off'
      ? `CAVEMAN MODE ACTIVE (${activeMode}) — session ruleset applies.`
      : null;

    // One write, so an unresolved-level notice and the per-turn reinforcement
    // can both land on the same turn. Only one hookSpecificOutput per hook run
    // is read, so emitting them separately would drop whichever came second.
    const context = [notice, reinforce].filter(Boolean).join('\n\n');
    if (context) {
      process.stdout.write(JSON.stringify({
        hookSpecificOutput: {
          hookEventName: "UserPromptSubmit",
          additionalContext: context
        }
      }));
    }
  } catch (e) {
    // Silent fail
  }
}

// StringDecoder semantics: a multi-byte character split across two chunks is
// held until it is complete, instead of each half being coerced to a lone
// replacement char by `'' + buffer`. Matters more now that the payload is
// parsed per chunk rather than once at EOF.
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => {
  input += chunk;
  // A partial payload throws here and we simply wait for more bytes.
  try { JSON.parse(input); } catch (e) { return; }
  handle(input);
  // pause() stops the flow but the 'data' listener has REFERENCED the stdin
  // handle, so the event loop stays alive until the host closes the write end.
  // On Windows that close lags arbitrarily (#729/#833), so the hook sat idle
  // with its work already done until the 5s budget expired and the host killed
  // it — the shape of #819 (timeouts on turns that measure ~56ms of real work).
  // unref() drops the handle from the loop without closing the fd, so we exit
  // as soon as stdout has flushed.
  process.stdin.pause();
  try { process.stdin.unref(); } catch (e) {}
});
// Abnormal stdin close (broken pipe, parent crash) emits 'error'; without a
// listener Node throws it as an uncaught exception and the hook exits
// non-zero — a spurious hook failure (#538). Hooks must always exit 0.
process.stdin.on('error', () => process.exit(0));
// Same failure, output side (#397): the harness can close its end of our
// stdout/stderr after this hook has already written a payload, and an
// unlistened 'error' there throws just as loudly.
for (const stream of [process.stdout, process.stderr]) {
  stream.on('error', () => process.exit(0));
}
process.stdin.on('end', () => handle(input));

#!/usr/bin/env node
// caveman — shared mode-change parser (#602)
//
// Single source of truth for interpreting a user prompt as a caveman mode
// change. Extracted from caveman-mode-tracker.js so the Claude Code hook and
// the opencode plugin can't drift out of sync with each other. The tracker's
// regexes are the reference behavior — every pattern below is copied from it
// verbatim; don't tighten or loosen a match here without a matching change
// (and test) on the tracker side.
//
// parseModeChange(prompt, { getDefaultMode, skipNaturalLanguage, expandedTpl, unwrapQuotes })
//   → { action: 'set', mode }  — caller should activate `mode`
//   → { action: 'clear' }      — caller should deactivate (delete the flag)
//   → null                     — prompt does not change state
//
// Options:
//   getDefaultMode      — required; () => resolved default mode string.
//                          Injected rather than required directly so the
//                          caller controls resolution (cwd, env, etc.).
//   skipNaturalLanguage — when true, skip deactivation/activation/brevity
//                          phrase matching entirely. Set this for prompt text
//                          that isn't the user's own words (e.g. a foreign
//                          slash-command envelope's <command-args>), so
//                          another command's arguments can't misfire our
//                          triggers.
//   expandedTpl         — when true, also recognize opencode's expanded
//                          command-template bodies (a typed "/caveman ultra"
//                          gets replaced by the command file's prose before
//                          this parser ever sees it). Claude Code prompts
//                          never take this shape, so Claude Code callers
//                          should leave this off.
//   unwrapQuotes        — when true, strip a single layer of matching quote
//                          characters wrapping the whole prompt (opencode's
//                          non-interactive `run` path delivers messages this
//                          way).

// Sibling require that tolerates the opencode install layout, where this
// file is copied next to a renamed `caveman-config.cjs` (the plugin dir is
// "type": "module", so a bare `.js` sibling would load as ESM). A plain
// `require('./caveman-config')` only auto-resolves the `.js` extension, so
// try that first (dev tree, standalone hook install) and fall back to the
// explicit `.cjs` name.
let cavemanConfig;
try {
  cavemanConfig = require('./caveman-config');
} catch (e) {
  cavemanConfig = require('./caveman-config.cjs');
}
const { VALID_MODES } = cavemanConfig;

// Modes handled by their own slash commands (/caveman-commit, etc.) — not
// selectable via /caveman <arg>.
const INDEPENDENT_MODES = new Set(['commit', 'review', 'compress']);

// Natural-language triggers run over the whole prompt, so any pasted text that
// merely QUOTES them fired them — a bug report quoting the /caveman-help card's
// own line ("Say \"stop caveman\" or \"normal mode\".") switched caveman off
// mid-task (#838). #537's envelope unwrap closed the slash-command path; this
// is the prose path, which needs no envelope.
//
// Blank quoted spans before matching. A prompt-length cap looked like the fix
// and is worse on both sides: it still fires on any short quoted line, and it
// silently breaks the compound instructions people actually type ("turn off
// caveman and write the release notes for ..."). That failure is the dangerous
// direction — a false activation is a nuisance, but a deactivation that is
// dropped in silence leaves the user unable to escape the mode with no
// feedback explaining why.
//
// Only " and ` count as delimiters. Apostrophes are far too common in ordinary
// English ("don't stop caveman, it's useful") and pairing on them would blank
// the command itself.
const QUOTED_SPAN_REGEX = /(["`])(?:(?!\1).)*\1/g;

// A mode argument with punctuation glued to it ("/caveman ultra; still too
// verbose") matched no mode, left the level untouched, and said nothing. Only
// parts[1] is ever read, so extra WORDS after the mode were already harmless;
// it is the trailing character that broke it. Modes are [a-z-] only, so
// stripping every trailing character outside that class is safe.
// Trailing punctuation only. A leading quote or bracket is stripped too so
// `/caveman "ultra"` resolves — asymmetric handling would leave a second,
// equally silent failure right next to the one being fixed.
function normalizeModeArg(arg) {
  return (arg || '').replace(/^[^a-z0-9]+/, '').replace(/[^a-z0-9-]+$/, '');
}

// Resolve a /caveman argument to a verdict. An argument that resolves to
// nothing returns 'unresolved' rather than null, so the caller can say so
// instead of failing silently. 'unresolved' is additive: applyModeChange in the
// opencode plugin acts only on 'set'/'clear' and ignores anything else.
function resolveModeArg(rawArg, getDefaultMode) {
  const arg = normalizeModeArg(rawArg);
  if (!arg) {
    // Only a genuinely ABSENT argument means "bare /caveman → activate at the
    // default". An argument that was present but normalized away is punctuation
    // like `/caveman ?` — plausibly someone asking for help, who should not be
    // switched into the mode by it.
    if (rawArg) return { action: 'unresolved' };
    const mode = getDefaultMode();
    return mode === 'off' ? { action: 'clear' } : { action: 'set', mode };
  }
  if (arg === 'off' || arg === 'stop' || arg === 'disable') return { action: 'clear' };
  // canonical alias — config stores wenyan-full as 'wenyan'
  if (arg === 'wenyan-full') return { action: 'set', mode: 'wenyan' };
  if (VALID_MODES.includes(arg) && !INDEPENDENT_MODES.has(arg)) return { action: 'set', mode: arg };
  // An independent mode IS a real mode, just not reachable this way. Saying
  // "not recognized" would deny a mode the user can see in the docs; name its
  // own command instead. Echoing `arg` here is safe precisely because it
  // matched this fixed whitelist — it is no longer free-form user text.
  if (INDEPENDENT_MODES.has(arg)) return { action: 'unresolved', independentMode: arg };
  // Bogus level: never silently overwrite with the default (#602). The
  // rejected string is untrusted input and is deliberately NOT echoed back —
  // it would land in model context.
  return { action: 'unresolved' };
}

function parseModeChange(promptRaw, options) {
  options = options || {};
  const getDefaultMode = options.getDefaultMode || cavemanConfig.getDefaultMode;

  let prompt = (promptRaw || '').trim();
  if (options.unwrapQuotes) {
    const wrapped = /^(["'`])([\s\S]*)\1$/.exec(prompt);
    if (wrapped) prompt = wrapped[2].trim();
  }
  // Capture the first line before whitespace collapse. The expandedTpl
  // templates (opencode's commands/caveman.md etc.) put $ARGUMENTS at the end
  // of the first line, followed by a blank line and then fixed boilerplate
  // ("If no level given, use full. If \"off\", deactivate."). Collapsing all
  // whitespace to single spaces (below) merges an EMPTY argument directly
  // into that boilerplate, so a bare `/caveman` with no level looked like the
  // level was the word "if" and got rejected as bogus. Extract the template
  // argument from this uncollapsed first line instead.
  const firstLine = prompt.toLowerCase().split(/\r?\n/, 1)[0];
  // Collapse whitespace so phrase triggers still match multiline prompts —
  // every regex below expects a single-line prompt (#598).
  prompt = prompt.toLowerCase().replace(/\s+/g, ' ');
  if (!prompt) return null;

  // Deactivation intent — computed FIRST so "turn caveman mode off" never
  // falls through to the activation patterns (#598), and applied with the
  // highest priority: it's what the tracker's original unconditional
  // end-of-function deactivation check amounted to.
  // Matched against nlPrompt (quoted spans blanked, see QUOTED_SPAN_REGEX) so a
  // prompt that CITES a trigger does not fire it. A prompt that starts with a
  // slash is a command invocation: its own text must not toggle our mode,
  // symmetric with the skipNaturalLanguage a foreign command envelope sets.
  const naturalLanguage = !options.skipNaturalLanguage && !prompt.startsWith('/');
  const nlPrompt = naturalLanguage ? prompt.replace(QUOTED_SPAN_REGEX, ' ') : '';

  const wantsOff = naturalLanguage && (
    /\b(stop|disable|deactivate|quit|exit|kill)\s+(the\s+)?caveman\b/.test(nlPrompt) ||
    /\bcaveman(\s+mode)?\s+(off|stop|disabled?)\b/.test(nlPrompt) ||
    /\bturn\s+off\s+(the\s+)?caveman\b/.test(nlPrompt) ||
    // "normal mode" only as a command (prompt-initial, optionally led by a
    // switch-back verb) or with caveman context — never mid-sentence for
    // e.g. vim's normal mode ("how do I exit vim normal mode").
    /^(please\s+)?(go\s+|back\s+to\s+|switch\s+(back\s+)?to\s+|return\s+to\s+)?normal\s+mode\b/.test(nlPrompt) ||
    (/\bnormal\s+mode\b/.test(nlPrompt) && /\bcaveman\b/.test(nlPrompt))
  );
  if (wantsOff) return { action: 'clear' };

  // opencode expands a typed "/caveman <level>" (and the independent-mode
  // commands) into the command file's prose before chat.message fires, so
  // the literal slash-command branch below never sees the original text.
  // Recover the level from each template's fixed prefix instead. This MUST
  // run before the generic NL-activation match below: "Activate caveman
  // mode: ultra" would otherwise trip the "activate ... caveman" trigger and
  // swallow the level, activating at the default instead (#602). Claude Code
  // prompts never take this shape, so gate behind expandedTpl (opencode-only).
  if (options.expandedTpl) {
    if (/^generate a commit message for the current staged changes\b/.test(prompt)) {
      return { action: 'set', mode: 'commit' };
    }
    if (/^review the current diff\b/.test(prompt)) {
      return { action: 'set', mode: 'review' };
    }
    if (/^compress the file at:/.test(prompt)) {
      return { action: 'set', mode: 'compress' };
    }
    const tpl = /^activate caveman mode:[ \t]*(\S*)/.exec(firstLine);
    if (tpl) return resolveModeArg(tpl[1], getDefaultMode);
  }

  if (naturalLanguage) {
    // Questions about caveman are not activation commands
    // ("what is caveman mode?", "does caveman lite drop articles?").
    const isQuestion =
      /^(what|whats|what's|how|why|when|where|who|does|do|did|is|are|can|could|would|should|tell me|explain)\b/.test(nlPrompt);

    // Natural language activation (e.g. "activate caveman", "turn on caveman
    // mode", "talk like caveman"). Also brevity requests ("less tokens",
    // "be brief/terse", "fewer tokens", "shorter answers") — but not when
    // scoped to a single section ("be brief in the summary"), which is a
    // one-off instruction, not a session-wide mode switch.
    if (!isQuestion) {
      if (/\b(activate|enable|start|turn on|use|switch to|want|give me)\b[^.]{0,40}\bcaveman\b/.test(nlPrompt) ||
          /\btalk like\b[^.]{0,40}\bcaveman\b/.test(nlPrompt) ||
          /\bcaveman\s+mode\s+(on|please|now)\b/.test(nlPrompt) ||
          /^caveman(\s+mode)?\s*[.!]*$/.test(nlPrompt) ||
          /\b(less tokens|fewer tokens|be brief|be terse|shorter answers)\b(?!\s+(in|for|on|about|when|during|with)\b)/.test(nlPrompt)) {
        const mode = getDefaultMode();
        // Mirrors the tracker exactly: a configured-off default makes this a
        // no-op (leave whatever flag state already exists), NOT a clear —
        // that's only what an explicit "/caveman" bare command does.
        return mode !== 'off' ? { action: 'set', mode } : null;
      }
    }
  }

  // Match /caveman commands. Marketplace plugin installs surface commands
  // namespaced as /caveman:caveman-<name> — accept both forms for every
  // skill (#599: only compress and stats had the namespaced variant).
  if (prompt.startsWith('/caveman')) {
    const parts = prompt.split(/\s+/);
    const cmd = parts[0]; // /caveman, /caveman-commit, /caveman-review, etc.
    const arg = parts[1] || '';

    if (cmd === '/caveman-commit' || cmd === '/caveman:caveman-commit') {
      return { action: 'set', mode: 'commit' };
    }
    if (cmd === '/caveman-review' || cmd === '/caveman:caveman-review') {
      return { action: 'set', mode: 'review' };
    }
    if (cmd === '/caveman-compress' || cmd === '/caveman:caveman-compress') {
      return { action: 'set', mode: 'compress' };
    }
    if (cmd === '/caveman' || cmd === '/caveman:caveman') {
      // Bare /caveman → activate at configured default; otherwise resolve the
      // level (punctuation-tolerant, bogus values reported not swallowed).
      return resolveModeArg(arg, getDefaultMode);
    }
  }

  return null;
}

module.exports = { parseModeChange, INDEPENDENT_MODES };

#!/usr/bin/env node
// caveman-stats — read the active Claude Code session log, print real token
// usage plus an estimated savings figure from the benchmark in benchmarks/.
//
// Run directly:    node hooks/caveman-stats.js
// Inside Claude:   /caveman-stats triggers this via the UserPromptSubmit hook.
// Hook integration passes --session-file <transcript_path> so we always read
// the active session, not whichever JSONL was modified most recently.

const fs = require('fs');
const path = require('path');
const os = require('os');
// caveman-config.js is a mandatory sibling, but an incomplete install leaves
// it absent. A bare top-level require turns that into an uncaught
// MODULE_NOT_FOUND stack trace, which the calling mode-tracker hook can only
// report as an unexplained failure (#848). Print one actionable line instead.
//
// Deliberately inlined rather than extracted into a shared helper: a shared
// loader would itself be one more sibling that can go missing, which is the
// exact failure this guards against.
let cavemanConfig;
let configFailure = null;
try {
  cavemanConfig = require('./caveman-config');
} catch (primary) {
  // The opencode install layout renames the sibling to `.cjs` (its plugin dir
  // is "type": "module"), same fallback caveman-parse.js already does. Gate the
  // retry on the error naming THIS module: a MODULE_NOT_FOUND thrown by a
  // require *inside* a sibling that loaded fine must not be re-reported as
  // "./caveman-config.cjs is missing", blaming a file never meant to exist.
  const message = String((primary && primary.message) || primary);
  if (primary && primary.code === 'MODULE_NOT_FOUND' && message.includes("'./caveman-config'")) {
    try { cavemanConfig = require('./caveman-config.cjs'); } catch (e) { /* report primary */ }
  }
  if (!cavemanConfig) {
    const absent = !fs.existsSync(path.join(__dirname, 'caveman-config.js'))
                && !fs.existsSync(path.join(__dirname, 'caveman-config.cjs'));
    // Distinguish "the sibling is absent" from "the sibling loaded but its own
    // require failed" — naming the wrong cause is worse than no message. Only
    // the first line of error.message: Node appends a multi-line "Require
    // stack:" block, the very noise this guard exists to remove.
    configFailure = absent
      ? 'caveman-config.js is missing from ' + __dirname + ' — the install is incomplete.'
      : 'caveman-config could not load — ' + message.split('\n')[0];
  }
}
// A module that LOADS but exports the wrong shape is the plugin-cache-drift
// case #848 describes; without this check the first use dereferences undefined.
if (cavemanConfig && !(typeof cavemanConfig.readFlag === 'function'
    && typeof cavemanConfig.appendFlag === 'function'
    && typeof cavemanConfig.readHistory === 'function'
    && typeof cavemanConfig.safeWriteFlag === 'function'
    && Array.isArray(cavemanConfig.VALID_MODES))) {
  configFailure = 'caveman-config loaded but is missing expected exports — the install is inconsistent.';
}
if (configFailure) {
  process.stderr.write('caveman-stats: ' + configFailure + '\n'
    + 'Run `/plugin update caveman`, or rerun install.sh for standalone hooks.\n');
  // Unlike the two style hooks, stats has no useful degraded output — every
  // figure it prints comes from the flag/history the config module owns.
  // Exiting non-zero lets the mode-tracker's existing catch substitute its
  // "could not run stats script" message rather than injecting a half-report.
  process.exit(1);
}
const { readFlag, appendFlag, readHistory, safeWriteFlag, VALID_MODES, MODE_LOG_BASENAME } = cavemanConfig;

// Per-session helpers, resolved individually and NOT added to the shape check
// above: a config module from before per-session state still produces correct
// (machine-wide) figures, and hard-failing stats over the newer exports would
// turn a working report into an error. Each stub is the pre-per-session read.
const resolveActiveMode = cavemanConfig.resolveActiveMode
  || ((dir) => { const m = readFlag(path.join(dir, '.caveman-active')); return (!m || m === 'off') ? null : m; });
const validateSessionId = cavemanConfig.validateSessionId || (() => null);
const sessionActivePath = cavemanConfig.sessionActivePath || (() => null);
const legacyFlagPath = cavemanConfig.legacyFlagPath || ((dir) => path.join(dir, '.caveman-active'));

// Mean per-task savings from benchmarks/results/*.json (avg_savings: 65 across
// 10 tasks, sonnet-4-20250514). Only 'full' has measured data; lite / ultra /
// wenyan modes show no estimate until benchmarked. Add an entry here when a new
// run is committed.
const COMPRESSION = { 'full': 0.65 };

// Per-turn INPUT cost the rules add: SKILL.md (~5 KB) is injected into
// context, plus the per-turn reinforcement the mode tracker emits. This is
// the ~1-1.5k/turn figure docs/HONEST-NUMBERS.md admits and #145/#677 flag as
// hidden — gross output savings alone can look great while the session is
// still net-negative. 1250 sits mid-range; override with
// CAVEMAN_RULE_OVERHEAD_TOKENS if you've measured your own setup.
const DEFAULT_RULE_OVERHEAD_TOKENS_PER_TURN = 1250;

function ruleOverheadPerTurn() {
  const raw = process.env.CAVEMAN_RULE_OVERHEAD_TOKENS;
  if (raw === undefined) return DEFAULT_RULE_OVERHEAD_TOKENS_PER_TURN;
  const n = Number(raw);
  return Number.isInteger(n) && n > 0 ? n : DEFAULT_RULE_OVERHEAD_TOKENS_PER_TURN;
}

// Approximate Anthropic public output-token pricing, USD per million.
// Match by model id prefix so this stays correct across point releases
// (e.g. claude-sonnet-4-20250514, claude-sonnet-4-7). Update from
// https://www.anthropic.com/pricing if a release changes the tier.
// Most-specific prefixes MUST come first — priceForModel returns the first match.
const MODEL_OUTPUT_PRICE_PER_M = [
  // Claude 5 family. Fable/Mythos (models.anthropic.com naming) sit at the
  // top $50/M tier; Opus 5 dropped to $25/M. Sonnet 5's $10/M rate is the
  // permanent standard price — the increase to $15/M planned for
  // 2026-09-01 was cancelled (see anthropic.com/docs/en/about-claude/pricing).
  ['claude-fable-5',   50.00],
  ['claude-mythos-5',  50.00],
  ['claude-opus-5',    25.00],
  ['claude-sonnet-5',  10.00],
  // Legacy Opus 4.0 / 4.1 (pre-4.5) billed at the old $75/M output tier,
  // including the dated ids (e.g. claude-opus-4-20250514).
  ['claude-opus-4-0',    75.00],
  ['claude-opus-4-1',    75.00],
  ['claude-opus-4-2025', 75.00],
  // Opus 4.5–4.8 dropped to $25/M output (rate card held since 4.5).
  ['claude-opus-4',      25.00],
  ['claude-sonnet-4',    15.00],
  ['claude-haiku-4',      5.00],   // Haiku 4.5 = $5/M output
  ['claude-3-5-sonnet',  15.00],
  ['claude-3-5-haiku',    4.00],
  ['claude-3-opus',      75.00],
];

function priceForModel(model) {
  if (!model) return null;
  for (const [prefix, price] of MODEL_OUTPUT_PRICE_PER_M) {
    if (model.startsWith(prefix)) return price;
  }
  return null;
}

function formatUsd(amount) {
  if (amount >= 1) return `$${amount.toFixed(2)}`;
  if (amount >= 0.01) return `$${amount.toFixed(3)}`;
  return `$${amount.toFixed(4)}`;
}

function findRecentSession(claudeDir) {
  const projectsDir = path.join(claudeDir, 'projects');
  let entries;
  try { entries = fs.readdirSync(projectsDir, { withFileTypes: true }); }
  catch { return null; }

  let best = null;
  const stack = entries.map(e => path.join(projectsDir, e.name));
  while (stack.length) {
    const p = stack.pop();
    let st;
    try { st = fs.statSync(p); } catch { continue; }
    if (st.isDirectory()) {
      try {
        for (const child of fs.readdirSync(p)) stack.push(path.join(p, child));
      } catch {}
    } else if (p.endsWith('.jsonl') && (!best || st.mtimeMs > best.mtime)) {
      best = { file: p, mtime: st.mtimeMs };
    }
  }
  return best ? best.file : null;
}

function parseSession(filePath) {
  let raw;
  try { raw = fs.readFileSync(filePath, 'utf8'); }
  catch { return { outputTokens: 0, cacheReadTokens: 0, turns: 0, model: null, messages: [] }; }

  let outputTokens = 0;
  let cacheReadTokens = 0;
  let turns = 0;
  let model = null;
  const messages = []; // per-message {ts, outputTokens} for mode attribution (#601)
  for (const line of raw.split('\n')) {
    if (!line.trim()) continue;
    let entry;
    try { entry = JSON.parse(line); } catch { continue; }
    if (entry.type !== 'assistant' || !entry.message) continue;
    const usage = entry.message.usage;
    if (!usage) continue;
    outputTokens    += usage.output_tokens           || 0;
    cacheReadTokens += usage.cache_read_input_tokens || 0;
    turns++;
    if (!model && entry.message.model) model = entry.message.model;
    const ts = entry.timestamp ? Date.parse(entry.timestamp) : NaN;
    messages.push({
      ts: Number.isFinite(ts) ? ts : null,
      outputTokens: usage.output_tokens || 0,
    });
  }
  return { outputTokens, cacheReadTokens, turns, model, messages };
}

// Detect *.original.md / *.md pairs left behind by caveman-compress. The
// presence of a *.original.md backup means the *.md sibling is a compressed
// memory file — every session start reads the compressed version, so the
// delta is per-session input-token savings (passive). Returns a summary or
// null if nothing was found in the given dirs.
function findCompressedPairs(dirs) {
  const pairs = [];
  for (const dir of dirs) {
    let entries;
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); }
    catch { continue; }
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith('.original.md')) continue;
      const base = entry.name.slice(0, -'.original.md'.length);
      const originalPath = path.join(dir, entry.name);
      const compressedPath = path.join(dir, `${base}.md`);
      let oSize, cSize;
      try {
        oSize = fs.statSync(originalPath).size;
        cSize = fs.statSync(compressedPath).size;
      } catch { continue; }
      if (oSize <= cSize) continue;
      pairs.push({ name: base, dir, originalSize: oSize, compressedSize: cSize });
    }
  }
  return pairs;
}

function summarizeCompressed(pairs) {
  if (!pairs || pairs.length === 0) return null;
  const totalOriginal = pairs.reduce((s, p) => s + p.originalSize, 0);
  const totalCompressed = pairs.reduce((s, p) => s + p.compressedSize, 0);
  const bytesSaved = totalOriginal - totalCompressed;
  // English prose runs ~4 chars per token. Label result as approximate so we
  // don't make claims tighter than the method warrants.
  const tokensSaved = Math.round(bytesSaved / 4);
  return { count: pairs.length, bytesSaved, tokensSaved };
}

// ── Per-mode attribution (#601) ─────────────────────────────────────────────
// The whole session's tokens must never be credited to whatever mode the flag
// happens to hold at stats time — a mid-session mode change would inflate the
// estimate (verbose tokens counted as compressed) or zero it (caveman tokens
// counted as uncompressed). The mode tracker + SessionStart hook append
// {ts, mode, prev} rows to .caveman-mode-log.jsonl on every actual transition;
// stats joins those timestamps against the session JSONL message timestamps.

// Read + validate the transition log. Returns rows sorted by ts.
//
// When sessionId is given, rows belonging to a DIFFERENT session are dropped.
// Without this the log is a machine-wide interleaving: a mode switch in window
// B lands between two of window A's messages and gets joined onto A's timeline,
// skewing A's savings estimate. Rows with no session_id predate the tagging and
// are kept — for a single-session user they are still the right answer, and
// discarding them would silently downgrade attribution to 'whole-session'.
function readModeLog(logPath, sessionId) {
  const wanted = validateSessionId(sessionId);
  const rows = [];
  for (const line of readHistory(logPath)) {
    let e;
    try { e = JSON.parse(line); } catch { continue; }
    if (!e || typeof e !== 'object' || !Number.isFinite(e.ts)) continue;
    if (wanted && e.session_id != null && e.session_id !== wanted) continue;
    const norm = (v) => (v == null ? null : (VALID_MODES.includes(String(v)) ? String(v) : undefined));
    const mode = norm(e.mode);
    const prev = norm(e.prev);
    if (mode === undefined || prev === undefined) continue; // reject non-whitelisted values
    rows.push({ ts: e.ts, mode, prev });
  }
  rows.sort((a, b) => a.ts - b.ts);
  return rows;
}

// Attribute each message's output tokens to the mode active when it was
// generated. Sources, most to least exact:
//   'log'           — the transition log covers the message (rows at/before its
//                     ts, or the first row's `prev` for the pre-inception span).
//   'flag-mtime'    — no log rows, but the flag was written mid-session: tokens
//                     from the write onward belong to the current mode; earlier
//                     tokens have UNKNOWN mode and are excluded, never guessed
//                     (no-fake-savings). Messages without timestamps are also
//                     unknown in this case.
//   'whole-session' — no log and no evidence of a mid-session change: the
//                     current mode covers the whole session (correct when the
//                     mode never changed; pre-#601 behavior).
// Returns { byMode: {modeKey: tokens}, unknownTokens, basis } where modeKey is
// a mode string or 'none' (caveman inactive).
function attributeByMode({ messages, modeLog, mode, flagMtimeMs, outputTokens }) {
  const currentKey = mode || 'none';
  const msgs = messages || [];
  let firstTs = null;
  for (const m of msgs) {
    if (m.ts != null && (firstTs === null || m.ts < firstTs)) firstTs = m.ts;
  }

  let events = modeLog || [];
  let basis = 'log';
  let prefixMode; // mode for messages before the first event (undefined = unknown)
  if (events.length === 0) {
    if (flagMtimeMs != null && firstTs != null && flagMtimeMs > firstTs) {
      // Flag written mid-session with no transition log: only the span from
      // the write onward is attributable. The write may have been a
      // reaffirmation of the same mode, but assuming so would guess savings
      // into existence — exclude the prefix instead.
      events = [{ ts: flagMtimeMs, mode: mode || null }];
      basis = 'flag-mtime';
      prefixMode = undefined;
    } else {
      return { byMode: { [currentKey]: outputTokens || 0 }, unknownTokens: 0, basis: 'whole-session' };
    }
  } else {
    // Every transition since log inception is recorded, so the span before
    // the first row ran under that row's `prev` mode.
    prefixMode = events[0].prev;
  }

  const byMode = {};
  let unknownTokens = 0;
  const add = (key, tokens) => { byMode[key] = (byMode[key] || 0) + tokens; };
  for (const m of msgs) {
    if (m.ts == null) { unknownTokens += m.outputTokens; continue; }
    let active;
    for (const ev of events) {
      if (ev.ts <= m.ts) active = ev;
      else break;
    }
    if (active !== undefined) add(active.mode || 'none', m.outputTokens);
    else if (prefixMode !== undefined) add(prefixMode || 'none', m.outputTokens);
    else unknownTokens += m.outputTokens;
  }
  return { byMode, unknownTokens, basis };
}

// Attribution shape for callers without a session log to join against
// (kept for formatStats/formatShare backward compatibility in tests).
function wholeSessionAttribution(mode, outputTokens) {
  return { byMode: { [mode || 'none']: outputTokens || 0 }, unknownTokens: 0, basis: 'whole-session' };
}

// Compute the savings figures we want to log/share for one session snapshot.
// Sums per-mode: only spans whose mode has benchmark data earn an estimate;
// unknown spans earn nothing.
function deriveSavings({ byMode, model }) {
  let estSavedTokens = 0;
  for (const [key, tokens] of Object.entries(byMode || {})) {
    const ratio = COMPRESSION[key];
    if (ratio == null || tokens <= 0) continue;
    estSavedTokens += Math.round(tokens / (1 - ratio)) - tokens;
  }
  const price = priceForModel(model);
  const estSavedUsd = price !== null ? (estSavedTokens / 1_000_000) * price : 0;
  return { estSavedTokens, estSavedUsd };
}

// Net token effect = output tokens saved minus the input tokens the rules
// cost. Savings are OUTPUT tokens, overhead is INPUT tokens — different
// buckets, but summing them is the only honest whole-budget delta (see
// docs/HONEST-NUMBERS.md). Never called with an unattributed savings figure —
// callers only invoke this where mode attribution and turn counts both exist.
function deriveNet({ estSavedTokens, turns }) {
  const overheadTokens = Math.max(0, turns || 0) * ruleOverheadPerTurn();
  return { overheadTokens, netTokens: (estSavedTokens || 0) - overheadTokens };
}

// Shared "rule overhead" + "net" lines for the session and lifetime views.
function netLines({ estSavedTokens, turns }) {
  const perTurn = ruleOverheadPerTurn();
  const { overheadTokens, netTokens } = deriveNet({ estSavedTokens, turns });
  const overhead = `Est. rule overhead:    ${overheadTokens.toLocaleString()} ` +
    `(input, ~${perTurn.toLocaleString()}/turn over ${turns} turn${turns === 1 ? '' : 's'})`;
  const net = netTokens >= 0
    ? `Est. net:              +${netTokens.toLocaleString()} (net saving after rule overhead)`
    : `Est. net:              ${netTokens.toLocaleString()} (caveman cost more than it saved for this workload — consider turning it off)`;
  return `${overhead}\n${net}`;
}

// Parse "7d", "12h" etc. to milliseconds. Returns null on invalid input.
function parseDuration(spec) {
  if (!spec) return null;
  const m = /^(\d+)([dh])$/.exec(spec.trim());
  if (!m) return null;
  const n = parseInt(m[1], 10);
  return m[2] === 'd' ? n * 86_400_000 : n * 3_600_000;
}

// Aggregate history into latest-per-session totals, optionally filtered to a
// time window. Returns { sessions, outputTokens, estSavedTokens, estSavedUsd }.
function aggregateHistory(historyPath, sinceMs) {
  const lines = readHistory(historyPath);
  const cutoff = sinceMs ? Date.now() - sinceMs : null;
  const latestPerSession = new Map();
  for (const line of lines) {
    let entry;
    try { entry = JSON.parse(line); } catch { continue; }
    if (!entry || typeof entry !== 'object') continue;
    if (cutoff !== null && (entry.ts || 0) < cutoff) continue;
    const id = entry.session_id || '_';
    const prev = latestPerSession.get(id);
    if (!prev || (entry.ts || 0) >= (prev.ts || 0)) latestPerSession.set(id, entry);
  }
  let outputTokens = 0, estSavedTokens = 0, estSavedUsd = 0;
  // Net (rule-overhead) figures only ever sum rows that actually logged a
  // turn count. Legacy history rows predate #145's `turns` field — folding
  // their savings into a net computed from someone else's turns would either
  // over- or under-state the overhead, so they're excluded from net entirely
  // (they still count toward the plain gross totals above, unchanged).
  let netSavedTokens = 0, netTurns = 0;
  for (const e of latestPerSession.values()) {
    outputTokens   += e.output_tokens     || 0;
    estSavedTokens += e.est_saved_tokens  || 0;
    estSavedUsd    += e.est_saved_usd     || 0;
    if (e.turns != null) {
      netSavedTokens += e.est_saved_tokens || 0;
      netTurns       += e.turns            || 0;
    }
  }
  return { sessions: latestPerSession.size, outputTokens, estSavedTokens, estSavedUsd, netSavedTokens, netTurns };
}

// Output-reduction share: saved / (saved + used) = the fraction of the
// would-be OUTPUT tokens that caveman avoided. That is the only ratio we can
// honestly compute from output counts alone. It is NOT a share of session or
// limit usage — input + cache tokens dominate agentic sessions, count against
// Pro/Max limits, and are not reduced by caveman, so real limit relief is far
// smaller (docs/HONEST-NUMBERS.md: session-level totals land ~14–21%, below
// zero on terse workloads). Never label this "usage" or "budget". Returns a
// rounded percent, or null when there is nothing measured to divide.
function outputReductionPct(savedTokens, usedTokens) {
  if (!Number.isFinite(savedTokens) || !Number.isFinite(usedTokens)) return null;
  if (savedTokens <= 0 || usedTokens < 0) return null;
  const total = savedTokens + usedTokens;
  if (total <= 0) return null;
  return Math.round((savedTokens / total) * 100);
}

function humanizeTokens(n) {
  if (!Number.isFinite(n) || n <= 0) return '0';
  if (n >= 1e6) return (n / 1e6).toFixed(1) + 'M';
  if (n >= 1e3) return (n / 1e3).toFixed(1) + 'k';
  return String(Math.round(n));
}

function formatHistory({ sessions, outputTokens, estSavedTokens, estSavedUsd, netSavedTokens, netTurns, since }) {
  const sep = '──────────────────────────────────';
  const window = since ? ` (last ${since})` : '';
  if (sessions === 0) {
    return `\nCaveman Stats — Lifetime${window}\n${sep}\nNo sessions logged yet — run /caveman-stats inside any session to start tracking.\n${sep}\n`;
  }
  const usdLine = estSavedUsd > 0 ? `Est. saved (USD):      ~${formatUsd(estSavedUsd)}\n` : '';
  const pct = outputReductionPct(estSavedTokens, outputTokens);
  const budgetLine = pct !== null
    ? `Est. output reduction: ~${pct}% (output tokens only, est.)\n`
    : '';
  // Only sessions that logged a turn count feed the net figure (older rows
  // predate #145) — omit rather than understate the overhead.
  const netBlock = netTurns > 0 ? netLines({ estSavedTokens: netSavedTokens, turns: netTurns }) + '\n' : '';
  return `\nCaveman Stats — Lifetime${window}\n${sep}\n` +
    `Sessions:   ${sessions.toLocaleString()}\n${sep}\n` +
    `Output tokens:         ${outputTokens.toLocaleString()}\n` +
    `Est. tokens saved:     ${estSavedTokens.toLocaleString()}\n` +
    netBlock + budgetLine + usdLine + sep + '\n';
}

// Single-line tweetable summary. Stays human-friendly when no ratio is known.
// Savings come from per-mode attribution (#601) so a mid-session mode change
// never inflates the shared number.
function formatShare({ outputTokens, turns, mode, model, attribution }) {
  if (turns === 0) {
    return '🪨 caveman armed but no turns yet — caveman.sh';
  }
  const attr = attribution || wholeSessionAttribution(mode, outputTokens);
  const { estSavedTokens, estSavedUsd } = deriveSavings({ byMode: attr.byMode, model });

  if (estSavedTokens > 0) {
    const usd = estSavedUsd > 0 ? ` (~${formatUsd(estSavedUsd)})` : '';
    return `🪨 Saved ${estSavedTokens.toLocaleString()} output tokens${usd} across ${turns} turns this session — caveman.sh`;
  }
  return `🪨 ${turns} turns, ${outputTokens.toLocaleString()} output tokens this session — caveman.sh`;
}

// Pure formatter — separated from main() so tests can pass synthetic inputs.
// `attribution` (from attributeByMode, #601) splits output tokens per mode;
// when omitted, the current mode is assumed for the whole session.
function formatStats({ outputTokens, cacheReadTokens, turns, mode, model, sessionPath, compressed, attribution }) {
  const sep = '──────────────────────────────────';
  const shortPath = sessionPath && sessionPath.length > 45
    ? '...' + sessionPath.slice(-45)
    : (sessionPath || '');

  if (turns === 0) {
    return `\nCaveman Stats\n${sep}\nNo conversation yet — stats available after first response.\n${sep}\n`;
  }

  const attr = attribution || wholeSessionAttribution(mode, outputTokens);
  const activeKeys = Object.keys(attr.byMode).filter(k => attr.byMode[k] > 0);
  // Uniform = every token ran under the CURRENT mode. Anything else — a
  // second mode, tokens under a mode the flag no longer shows, or spans we
  // could not attribute — gets the per-mode breakdown below.
  const uniform = attr.unknownTokens === 0 &&
    (activeKeys.length === 0 || (activeKeys.length === 1 && activeKeys[0] === (mode || 'none')));

  const ratio = COMPRESSION[mode] != null ? COMPRESSION[mode] : null;
  const price = priceForModel(model);

  let savings;
  let footer = '';
  if (!uniform) {
    const { estSavedTokens, estSavedUsd } = deriveSavings({ byMode: attr.byMode, model });
    const lines = [attr.basis === 'flag-mtime'
      ? 'Mode was set mid-session — only output after the change is attributed:'
      : 'Mode changed mid-session — output attributed per mode:'];
    for (const key of activeKeys) {
      const tokens = attr.byMode[key];
      const r = COMPRESSION[key];
      const label = key === 'none' ? 'caveman off' : key;
      const note = r != null
        ? `est. ${(Math.round(tokens / (1 - r)) - tokens).toLocaleString()} saved`
        : 'no benchmark estimate';
      lines.push(`  ${label}: ${tokens.toLocaleString()} tokens (${note})`);
    }
    if (attr.unknownTokens > 0) {
      lines.push(`  unattributed: ${attr.unknownTokens.toLocaleString()} tokens (mode unknown — excluded from estimate)`);
    }
    lines.push(`Est. tokens saved:     ${estSavedTokens.toLocaleString()}`);
    if (estSavedUsd > 0) lines.push(`Est. saved (USD):      ~${formatUsd(estSavedUsd)}`);
    savings = lines.join('\n');

    footer = 'Savings est. from benchmarks/ (mean per-task), applied only to spans whose mode is known.';
    if (estSavedUsd > 0) footer += ` Pricing for ${model}.`;
    if (attr.basis === 'flag-mtime') {
      footer += ' Tokens before the mode change could not be attributed and are excluded rather than guessed.';
    } else if (attr.unknownTokens > 0) {
      footer += ' Unattributed tokens are excluded rather than guessed.';
    }
    footer += ' Reduction is of output tokens only; input/cache usage is unchanged.';
  } else if (ratio !== null) {
    const estNormal = Math.round(outputTokens / (1 - ratio));
    const estSaved = estNormal - outputTokens;
    let usdLine = '';
    if (price !== null) {
      const usd = (estSaved / 1_000_000) * price;
      usdLine = `Est. saved (USD):      ~${formatUsd(usd)}\n`;
      footer = `Savings est. from benchmarks/ (mean per-task). Pricing for ${model}. Actual varies by task.`;
    } else {
      footer = 'Savings est. from benchmarks/ (mean per-task). Actual varies by task.';
    }
    // No "% of your usage/budget" line here on purpose: from output tokens
    // alone the only computable ratio is the output reduction already shown
    // on the line above, and input + cache tokens (which dominate agentic
    // sessions and count against Pro/Max limits) are untouched by caveman —
    // any session-usage % would overstate real limit relief. See
    // docs/HONEST-NUMBERS.md.
    footer += ' Reduction is of output tokens only; input/cache usage is unchanged.';
    footer += ` Net subtracts the rules' est. input cost (~${ruleOverheadPerTurn().toLocaleString()}/turn — docs/HONEST-NUMBERS.md).`;
    savings = (`Est. without caveman:  ${estNormal.toLocaleString()}\n` +
              `Est. tokens saved:     ${estSaved.toLocaleString()} (~${Math.round(ratio * 100)}% of output)\n` +
              usdLine).replace(/\n$/, '');
    // Net only makes sense where the savings figure above is unambiguous: a
    // single benchmarked mode ran the whole span (uniform) with a known turn
    // count. Mixed-mode or partially-unattributed spans (the !uniform branch
    // above) intentionally get no net line rather than a guessed one.
    if (turns > 0) savings += '\n' + netLines({ estSavedTokens: estSaved, turns });
  } else if (mode && mode !== 'off') {
    savings = `No savings estimate for '${mode}' mode — only 'full' has benchmark data.`;
  } else {
    savings = 'Caveman not active this session.';
  }

  let memoryLine = '';
  if (compressed && compressed.count > 0) {
    const tokensApprox = compressed.tokensSaved.toLocaleString();
    memoryLine = `${sep}\nMemory compressed:     ${compressed.count} file${compressed.count === 1 ? '' : 's'}, ` +
      `~${tokensApprox} tokens saved per session start (approx)\n`;
  }

  return `\nCaveman Stats\n${sep}\n` +
    (shortPath ? `Session:  ${shortPath}\n` : '') +
    `Turns:    ${turns}\n${sep}\n` +
    `Output tokens:         ${outputTokens.toLocaleString()}\n` +
    `Cache-read tokens:     ${cacheReadTokens.toLocaleString()}\n${sep}\n` +
    `${savings}\n` +
    memoryLine +
    (footer ? footer + '\n' : '');
}

function main() {
  const args = process.argv.slice(2);
  const i = args.indexOf('--session-file');
  const sessionFileArg = i !== -1 ? args[i + 1] : null;
  const sessionIdIdx = args.indexOf('--session-id');
  const sessionIdArg = sessionIdIdx !== -1 ? args[sessionIdIdx + 1] : null;
  const share = args.includes('--share');
  const all = args.includes('--all');
  const sinceIdx = args.indexOf('--since');
  const sinceArg = sinceIdx !== -1 ? args[sinceIdx + 1] : null;

  const claudeDir = process.env.CLAUDE_CONFIG_DIR || path.join(os.homedir(), '.claude');
  const historyPath = path.join(claudeDir, '.caveman-history.jsonl');

  // Lifetime aggregation paths short-circuit before we need a live session.
  if (all || sinceArg) {
    const sinceMs = parseDuration(sinceArg);
    if (sinceArg && sinceMs === null) {
      process.stderr.write(`caveman-stats: --since takes Nh or Nd (e.g. 7d, 24h), got: ${sinceArg}\n`);
      process.exit(2);
    }
    const agg = aggregateHistory(historyPath, sinceMs);
    process.stdout.write(formatHistory({ ...agg, since: sinceArg || null }));
    return;
  }

  const sessionFile = sessionFileArg || findRecentSession(claudeDir);

  if (!sessionFile) {
    process.stderr.write('caveman-stats: no Claude Code session found.\n');
    process.exit(1);
  }

  const parsed = parseSession(sessionFile);

  // Session id: the hook forwards --session-id from the UserPromptSubmit
  // payload. Falling back to the transcript filename is not a guess — Claude
  // Code names transcripts by session id, which is why the lifetime history has
  // always keyed on it.
  const sessionId = validateSessionId(sessionIdArg)
    || validateSessionId(path.basename(sessionFile, '.jsonl'));

  // Read whichever layer holds this session's state, and take the mtime from
  // that same file so the 'flag-mtime' attribution fallback measures the right
  // thing. resolveActiveMode collapses a durable 'off' to null, matching the
  // pre-existing "no flag file means no mode" contract the formatters expect.
  const sessionPath = sessionActivePath(claudeDir, sessionId);
  const flagPath = (sessionPath && fs.existsSync(sessionPath))
    ? sessionPath
    : legacyFlagPath(claudeDir);
  const mode = resolveActiveMode(claudeDir, sessionId);

  // #601: attribute tokens to the mode active when each message happened,
  // via the transition log the hooks maintain (fallbacks documented on
  // attributeByMode). Never credit the whole session to the current flag.
  let flagMtimeMs = null;
  try { flagMtimeMs = fs.statSync(flagPath).mtimeMs; } catch (e) {}
  const modeLog = readModeLog(path.join(claudeDir, MODE_LOG_BASENAME), sessionId);
  const attribution = attributeByMode({
    messages: parsed.messages,
    modeLog,
    mode,
    flagMtimeMs,
    outputTokens: parsed.outputTokens,
  });

  // Append a snapshot of this session's totals to the lifetime log. Multiple
  // /caveman-stats calls in one session emit multiple lines for the same
  // session_id; aggregateHistory keeps only the latest per session_id.
  if (parsed.turns > 0) {
    const { estSavedTokens, estSavedUsd } = deriveSavings({ byMode: attribution.byMode, model: parsed.model });
    appendFlag(historyPath, JSON.stringify({
      ts: Date.now(),
      session_id: sessionId || path.basename(sessionFile, '.jsonl'),
      mode: mode || null,
      model: parsed.model || null,
      output_tokens: parsed.outputTokens,
      turns: parsed.turns,
      est_saved_tokens: estSavedTokens,
      est_saved_usd: estSavedUsd,
    }));

    // Statusline suffix: tiny pre-rendered string the shell statusline can
    // cat without parsing JSONL. Updated on every /caveman-stats run.
    // Routed through safeWriteFlag — the suffix path is predictable and
    // user-owned, same symlink-clobber surface as the .caveman-active flag.
    const agg = aggregateHistory(historyPath, null);
    const suffix = agg.estSavedTokens > 0 ? `⛏  ${humanizeTokens(agg.estSavedTokens)}` : '';
    safeWriteFlag(path.join(claudeDir, '.caveman-statusline-suffix'), suffix);
  }

  if (share) {
    process.stdout.write(formatShare({ ...parsed, mode, attribution }) + '\n');
  } else {
    const scanDirs = [claudeDir, process.cwd()].filter((d, i, a) => a.indexOf(d) === i);
    const compressed = summarizeCompressed(findCompressedPairs(scanDirs));
    process.stdout.write(formatStats({ ...parsed, mode, sessionPath: sessionFile, compressed, attribution }));
  }
}

if (require.main === module) main();

module.exports = {
  formatStats, formatShare, formatHistory, aggregateHistory, parseDuration, deriveSavings,
  deriveNet, ruleOverheadPerTurn, parseSession, priceForModel, formatUsd, COMPRESSION,
  MODEL_OUTPUT_PRICE_PER_M, findCompressedPairs, summarizeCompressed, humanizeTokens,
  outputReductionPct, readModeLog, attributeByMode,
};

[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
$ClaudeDir = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $HOME ".claude" }

# Claude Code sends session JSON on stdin, including session_id. We use it to
# read THIS window's mode instead of a machine-wide flag — otherwise every
# window renders whichever mode was set last.
#
# Two guards keep this from wedging the status bar, mirroring the bash port:
#   1. IsInputRedirected — an interactive console is never read from.
#   2. ReadToEndAsync + Wait(1000) — a hard 1s ceiling if stdin is an open
#      pipe that never closes. Normally EOF arrives immediately.
$SessionId = ""
if ([Console]::IsInputRedirected) {
    try {
        $task = [Console]::In.ReadToEndAsync()
        if ($task.Wait(1000)) {
            $payload = $task.Result
            if ($payload) {
                $SessionId = [string](ConvertFrom-Json $payload).session_id
            }
        }
    } catch {
        $SessionId = ""
    }
}

# The id becomes part of a path, so whitelist its alphabet. Anything else —
# including empty — falls back to the legacy machine-wide flag.
if ($SessionId -notmatch '^[A-Za-z0-9_-]{1,128}$') { $SessionId = "" }

$Flag = Join-Path $ClaudeDir ".caveman-active"
if ($SessionId) {
    $SessionFlag = Join-Path (Join-Path $ClaudeDir ".caveman-sessions") "$SessionId.mode"
    if (Test-Path -LiteralPath $SessionFlag) { $Flag = $SessionFlag }
}

if (-not (Test-Path -LiteralPath $Flag)) { exit 0 }

# Refuse reparse points (symlinks / junctions) and oversized files. Without
# this, a local attacker could point the flag at a secret file and have the
# statusline render its bytes (including ANSI escape sequences) to the terminal
# every keystroke.
try {
    $Item = Get-Item -LiteralPath $Flag -Force -ErrorAction Stop
    if ($Item.Attributes -band [System.IO.FileAttributes]::ReparsePoint) { exit 0 }
    if ($Item.Length -gt 64) { exit 0 }
} catch {
    exit 0
}

$Mode = ""
try {
    $Raw = Get-Content -LiteralPath $Flag -TotalCount 1 -ErrorAction Stop
    if ($null -ne $Raw) { $Mode = ([string]$Raw).Trim() }
} catch {
    exit 0
}

# Strip anything outside [a-z0-9-] — blocks terminal-escape and OSC hyperlink
# injection via the flag contents. Then whitelist-validate.
$Mode = $Mode.ToLowerInvariant()
$Mode = ($Mode -replace '[^a-z0-9-]', '')

$Valid = @('off','lite','full','ultra','wenyan-lite','wenyan','wenyan-full','wenyan-ultra','commit','review','compress')
if (-not ($Valid -contains $Mode)) { exit 0 }

# Durable off: caveman is deactivated for this session. Render nothing at all,
# matching what an absent flag does — never "[CAVEMAN:OFF]", which would read
# as a caveman mode rather than the absence of one.
if ($Mode -eq "off") { exit 0 }

$Esc = [char]27
if ([string]::IsNullOrEmpty($Mode) -or $Mode -eq "full") {
    [Console]::Write("${Esc}[38;5;172m[CAVEMAN]${Esc}[0m")
} else {
    $Suffix = $Mode.ToUpperInvariant()
    [Console]::Write("${Esc}[38;5;172m[CAVEMAN:$Suffix]${Esc}[0m")
}

# Savings suffix: on by default. Opt out via CAVEMAN_STATUSLINE_SAVINGS=0.
# Reads a pre-rendered string written by caveman-stats.js. Refuses reparse
# points and strips control bytes (matches statusline.sh hardening). Until
# /caveman-stats has run at least once, the suffix file is absent and nothing
# is rendered — safe default for fresh installs.
if ($env:CAVEMAN_STATUSLINE_SAVINGS -ne "0") {
    $SavingsFile = Join-Path $ClaudeDir ".caveman-statusline-suffix"
    if (Test-Path $SavingsFile) {
        try {
            $SavingsItem = Get-Item -LiteralPath $SavingsFile -Force -ErrorAction Stop
            if (-not ($SavingsItem.Attributes -band [System.IO.FileAttributes]::ReparsePoint) -and
                $SavingsItem.Length -le 64) {
                $Savings = (Get-Content -LiteralPath $SavingsFile -Encoding UTF8 -Raw -ErrorAction Stop).TrimEnd()
                $Savings = ($Savings -replace '[\x00-\x1F]', '')
                if ($Savings.Length -gt 0) {
                    [Console]::Write(" ${Esc}[38;5;172m$Savings${Esc}[0m")
                }
            }
        } catch {}
    }
}

# caveman — one-command hook installer for Claude Code (Windows PowerShell)
# Installs: SessionStart hook (auto-load rules) + UserPromptSubmit hook (mode tracking)
# Usage: powershell -ExecutionPolicy Bypass -File src\hooks\install.ps1
#   or:  powershell -ExecutionPolicy Bypass -File src\hooks\install.ps1 -Force
#   or (remote, no -Force support via pipe):
#        irm https://raw.githubusercontent.com/JuliusBrussee/caveman/main/src/hooks/install.ps1 | iex
#   Note: irm ... | iex cannot pass -Force. For force reinstall, save the file and run with -File.
param(
    [switch]$Force
)

$ErrorActionPreference = "Stop"

# Require node
if (-not (Get-Command node -ErrorAction SilentlyContinue)) {
    Write-Host "ERROR: 'node' is required to install the caveman hooks (used to merge" -ForegroundColor Red
    Write-Host "       the hook config into settings.json safely)." -ForegroundColor Red
    Write-Host "       Install Node.js from https://nodejs.org and re-run this script." -ForegroundColor Red
    exit 1
}

$ClaudeDir = if ($env:CLAUDE_CONFIG_DIR) { $env:CLAUDE_CONFIG_DIR } else { Join-Path $env:USERPROFILE ".claude" }
$HooksDir = Join-Path $ClaudeDir "hooks"
$Settings = Join-Path $ClaudeDir "settings.json"
$RepoUrl = "https://raw.githubusercontent.com/JuliusBrussee/caveman/main/src/hooks"

$HookFiles = @("package.json", "caveman-config.js", "caveman-parse.js", "caveman-activate.js", "caveman-mode-tracker.js", "caveman-stats.js", "caveman-statusline.sh", "caveman-statusline.ps1", "cavecrew-model-overrides.js")

# Resolve source — works from repo clone or remote
$ScriptDir = if ($PSScriptRoot) { $PSScriptRoot } else { $null }

# Check if already installed (unless -Force). Older installs only had two hook
# files, so require the full current set plus the hook registrations before we
# short-circuit.
if (-not $Force) {
    $AllFilesPresent = $true
    foreach ($hook in $HookFiles) {
        if (-not (Test-Path (Join-Path $HooksDir $hook))) {
            $AllFilesPresent = $false
            break
        }
    }

    $HooksWired = $false
    $HasStatusLine = $false
    if ($AllFilesPresent -and (Test-Path $Settings)) {
        try {
            $settingsObj = Get-Content $Settings -Raw | ConvertFrom-Json
            # Probe for the exact script we wire for this event, not a bare
            # 'caveman' substring — that also matches user hooks merely
            # mentioning the word in a path (#593), which made us skip wiring
            # and silently leave caveman inactive. Mirrors install.sh.
            $hasCavemanHook = {
                param([string]$eventName, [string]$script)
                if (-not $settingsObj.hooks) { return $false }
                $entries = $settingsObj.hooks.$eventName
                if (-not $entries) { return $false }
                foreach ($entry in $entries) {
                    if ($entry.hooks) {
                        foreach ($hookDef in $entry.hooks) {
                            if ($hookDef.command -and $hookDef.command.Contains($script)) {
                                return $true
                            }
                        }
                    }
                }
                return $false
            }
            $HooksWired = (& $hasCavemanHook "SessionStart" "caveman-activate.js") `
                -and (& $hasCavemanHook "UserPromptSubmit" "caveman-mode-tracker.js")
            $HasStatusLine = $null -ne $settingsObj.statusLine
        } catch {
            $HooksWired = $false
            $HasStatusLine = $false
        }
    }

    if ($AllFilesPresent -and $HooksWired -and $HasStatusLine) {
        Write-Host "Caveman hooks already installed in $HooksDir"
        Write-Host "  Re-run with -Force to overwrite: powershell -File hooks\install.ps1 -Force"
        Write-Host ""
        Write-Host "Nothing to do. Hooks are already in place."
        exit 0
    }
}

if ($Force -and (Test-Path (Join-Path $HooksDir "caveman-activate.js"))) {
    Write-Host "Reinstalling caveman hooks (-Force)..."
} else {
    Write-Host "Installing caveman hooks..."
}

# 1. Ensure hooks dir exists
if (-not (Test-Path $HooksDir)) {
    New-Item -ItemType Directory -Path $HooksDir -Force | Out-Null
}

# 2. Copy or download hook files
foreach ($hook in $HookFiles) {
    $dest = Join-Path $HooksDir $hook
    $localSource = if ($ScriptDir) { Join-Path $ScriptDir $hook } else { $null }

    if ($localSource -and (Test-Path $localSource)) {
        Copy-Item $localSource $dest -Force
    } else {
        Invoke-WebRequest -Uri "$RepoUrl/$hook" -OutFile $dest -UseBasicParsing
    }
    Write-Host "  Installed: $dest"
}

# 3. Wire hooks + statusline into settings.json (idempotent)
if (-not (Test-Path $Settings)) {
    Set-Content -Path $Settings -Value "{}"
}

# Back up existing settings.json before touching it. Back up ONCE: without the
# Test-Path guard a -Force reinstall overwrites the only pre-caveman copy with
