          e.hooks && e.hooks.some(h => h.command && h.command.includes(script))
        );
      process.exit(
        hasCavemanHook('SessionStart', 'caveman-activate.js') &&
        hasCavemanHook('UserPromptSubmit', 'caveman-mode-tracker.js') &&
        !!settings.statusLine
          ? 0
          : 1
